WN.lb(34,{"mt_ahSqW_kK1b":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Solid to liquid is…","choices":["melting","freezing","condensing"],"answer":0,"hint":"Ice cream.","explain":"Melting."},{"type":"mc","id":"m2","prompt":"Liquid to gas is…","choices":["evaporating","freezing","melting"],"answer":0,"hint":"Puddles dry up.","explain":"Evaporating."},{"type":"mc","id":"m3","prompt":"Which separates sand from water?","choices":["filter","magnet","sieve with big holes"],"answer":0,"hint":"Sand is fine and insoluble.","explain":"A filter."},{"type":"mc","id":"m4","prompt":"Which gets salt from salt water?","choices":["evaporate","filter","magnet"],"answer":0,"hint":"Salt is dissolved.","explain":"Evaporate the water."},{"type":"numeric","id":"m5","prompt":"{n} g of sand and {m} g of salt are mixed. You remove the sand. How many grams are left?","answer":"m","hint":"Only salt.","explain":"{m} g.","params":{"n":[10,40],"m":[5,30]}},{"type":"numeric","id":"m6","prompt":"You do {n} separations, {m} with a filter. How many without a filter?","answer":"n-m","hint":"Take away.","explain":"{=n-m}.","params":{"n":[5,9],"m":[1,4]}},{"type":"mc","id":"m7","prompt":"Liquid to solid is…","choices":["freezing","melting","evaporating"],"answer":0,"hint":"Ice cubes.","explain":"Freezing."}]},"practice":[{"type":"mc","id":"p1","prompt":"Gas turning to liquid is…","choices":["condensing","melting","freezing"],"answer":0,"hint":"Drops on a cold window.","explain":"Condensing."},{"type":"mc","id":"p2","prompt":"Which separates iron filings from sand?","choices":["a magnet","a sieve","evaporating"],"answer":0,"hint":"Iron is magnetic.","explain":"Use a magnet."},{"type":"numeric","id":"p3","prompt":"A sieve catches {n} stones out of {=n+m}. How many go through?","answer":"m","hint":"Take away.","explain":"{m}.","params":{"n":[1,6],"m":[1,6]}},{"type":"numeric","id":"p4","prompt":"You separate {n} paper clips with a magnet, {m} at a time. How many goes? ({n} is a multiple of {m})","answer":"n/m","hint":"Share.","explain":"{n} ÷ {m} = {=n/m}.","params":{"n":[6,12],"m":[2,3]},"where":"n%m==0"}],"explain":{"kid":["Melt: solid to liquid. Freeze: liquid to solid. Evaporate: liquid to gas. Condense: gas to liquid.","A sieve catches big bits. A filter catches tiny bits that do not dissolve. A magnet pulls out iron."],"adult":["The words come in pairs. Melt and freeze. Evaporate and condense. To get a solid back after dissolving, evaporate the water.","To separate a mixture, ask how the parts differ. Size: use a sieve. Does it dissolve? Filter out what does not, then evaporate to get back what does. Is it iron? Use a magnet."]},"familyTip":"Mix dried peas, rice and paper clips. Ask how to separate them, then try it."},"mt_UKmtuAsSLN":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Dissolving sugar in tea is…","choices":["reversible","irreversible"],"answer":0,"hint":"Evaporate the water.","explain":"Sugar is left behind: reversible."},{"type":"mc","id":"m2","prompt":"Cooking an egg is…","choices":["irreversible","reversible"],"answer":0,"hint":"Can you uncook it?","explain":"A new material forms."},{"type":"mc","id":"m3","prompt":"A reversible change makes…","choices":["no new material","a new material","only gas"],"answer":0,"hint":"Same stuff.","explain":"No new material."},{"type":"mc","id":"m4","prompt":"Ice is taken out of the freezer and warms up. What happens?","choices":["It melts back to water","It turns into a new material","It stays ice for ever"],"answer":0,"hint":"Reversible.","explain":"It melts back into water: the same material."},{"type":"numeric","id":"m5","prompt":"{n} g of wax melts. What mass of wax sets again, in g?","answer":"n","hint":"Nothing lost.","explain":"{n} g.","params":{"n":[10,60]}},{"type":"numeric","id":"m6","prompt":"{n} changes: {m} are reversible. How many are irreversible?","answer":"n-m","hint":"Take away.","explain":"{=n-m}.","params":{"n":[5,9],"m":[1,4]}},{"type":"mc","id":"m7","prompt":"Mixing sand and gravel is…","choices":["reversible (sieve them)","irreversible"],"answer":0,"hint":"Can you sort them out?","explain":"A sieve separates them."}]},"practice":[{"type":"mc","id":"p1","prompt":"Melting chocolate is…","choices":["reversible","irreversible"],"answer":0,"hint":"Cool it.","explain":"It sets again: reversible."},{"type":"mc","id":"p2","prompt":"Burning paper is…","choices":["irreversible","reversible"],"answer":0,"hint":"Can you get the paper back?","explain":"Ash cannot become paper: irreversible."},{"type":"numeric","id":"p3","prompt":"{n} ice cubes melt, then all refreeze. How many ice cubes?","answer":"n","hint":"Same as before.","explain":"{n} again.","params":{"n":[3,9]}},{"type":"numeric","id":"p4","prompt":"You dissolve {n} g of salt and evaporate the water. How many grams of salt do you get back?","answer":"n","hint":"Reversible.","explain":"{n} g.","params":{"n":[5,30]}}],"explain":{"kid":["Melt ice and you get water. Freeze it and you get ice back. That change can go back, so it is reversible.","No new material is made. It is still water."],"adult":["Changes of state (melting, freezing, boiling, condensing), dissolving and mixing are reversible: the same material comes back. Burning, rusting and cooking make new materials, so they are irreversible.","A good test: can you get the starting materials back by a simple method such as cooling, heating, filtering or evaporating? If yes, it is reversible."]},"familyTip":"Make ice lollies from juice, then melt one. Is it the same juice? Now toast bread: can you untoast it?"},"mt_jg2oNKpNw9":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A neutral atom has atomic number {z}. How many electrons does it have?","answer":"z","hint":"In a neutral atom the charges balance.","explain":"{z} protons need {z} electrons to balance, so {z}.","params":{"z":[2,20]}},{"type":"mc","id":"m2","prompt":"Carbon-12 and carbon-14 are both carbon. What is different about them?","choices":["The number of neutrons","The number of protons","The number of electrons in a neutral atom"],"answer":0,"hint":"The element stays the same, so the protons stay the same.","explain":"They are isotopes: both have 6 protons, but carbon-14 has 8 neutrons instead of 6."},{"type":"numeric","id":"m3","prompt":"The symbol for an atom shows {=z*2+n} on top and {z} at the bottom. How many neutrons?","answer":"z+n","hint":"Top number minus bottom number.","explain":"{=z*2+n} − {z} = {=z+n} neutrons.","params":{"z":[3,20],"n":[0,4]}},{"type":"mc","id":"m4","prompt":"Chlorine has atomic number 17. How many electrons are in a chloride ion, Cl⁻?","choices":["18","16","17"],"answer":0,"hint":"A negative charge means the atom has gained electrons.","explain":"17 protons; a −1 charge means one extra electron, so 18."},{"type":"mc","id":"m5","prompt":"Why do we ignore electrons when working out the mass number?","choices":["Their mass is tiny compared with protons and neutrons","They have no mass at all","They are not part of the atom"],"answer":0,"hint":"Compare the masses of the three particles.","explain":"An electron is about 1/1840 of the mass of a proton, so it barely changes the total. It does have some mass."},{"type":"numeric","id":"m6","prompt":"An ion has {p} protons and a charge of +2. How many electrons does it have?","answer":"p-2","hint":"+2 means two more protons than electrons.","explain":"{p} − 2 = {=p-2} electrons.","params":{"p":[4,20]}},{"type":"mc","id":"m7","prompt":"An atom gains a proton. What happens?","choices":["It becomes a different element","It becomes an isotope of the same element","It becomes a negative ion"],"answer":0,"hint":"Which number decides the element?","explain":"The atomic number goes up by one, so it is the next element in the periodic table."}]},"practice":[{"type":"mc","id":"p1","prompt":"An atom has 8 protons, 8 neutrons and 8 electrons. Which number tells you which element it is?","choices":["The 8 protons","The 8 neutrons","The 8 electrons"],"answer":0,"hint":"Which particle can never change without the element changing too?","explain":"The protons. 8 protons is always oxygen; the atomic number of oxygen is 8."},{"type":"numeric","id":"p2","prompt":"An atom has atomic number {z} and mass number {=z*2+n}. How many neutrons does it have?","answer":"z+n","hint":"Neutrons = mass number − atomic number.","explain":"{=z*2+n} − {z} = {=z+n} neutrons.","params":{"z":[3,20],"n":[0,4]}},{"type":"numeric","id":"p3","prompt":"An atom has {p} protons and {n} neutrons. What is its mass number?","answer":"p+n","hint":"Add the particles in the nucleus.","explain":"Mass number = protons + neutrons = {p} + {n} = {=p+n}.","params":{"p":[3,20],"n":[3,22]}},{"type":"mc","id":"p4","prompt":"A sodium atom (11 protons) loses one electron. What is it now?","choices":["A sodium ion with charge +1","A neon atom","A sodium ion with charge −1"],"answer":0,"hint":"Count the charges: 11 positive protons, and how many negative electrons now?","explain":"It still has 11 protons, so it is still sodium. 11 − 10 = +1, so it is the ion Na⁺."}],"explain":{"kid":["An atom has a tiny centre called the nucleus. It holds protons and neutrons. Electrons move around the outside.","The number of protons is the atomic number. It tells you the element. Every carbon atom has 6 protons. If it had 7, it would be nitrogen.","The mass number is protons plus neutrons. Electrons are so light that we do not count them.","So neutrons = mass number − atomic number. Carbon-14 has 14 − 6 = 8 neutrons."],"adult":["A nuclear symbol such as ²³₁₁Na shows the mass number A (protons + neutrons) on top and the atomic number Z (protons) below. Neutrons = A − Z, so sodium-23 has 12 neutrons.","Z defines the element and its place in the periodic table. Atoms of the same element with different numbers of neutrons are isotopes: same chemistry, different mass. Carbon-12 and carbon-14 are both carbon.","A proton carries +1, an electron −1, and a neutron no charge. A neutral atom has as many electrons as protons. Losing electrons gives a positive ion (Na⁺ has 10), gaining them gives a negative ion (Cl⁻ has 18).","Common slips: taking the mass number as the number of neutrons, swapping the two numbers, and thinking that a charge changes the element. Only the proton count does that."]},"familyTip":"Pick an element from a periodic table poster or a food label (sodium, calcium, iron). Read off its atomic number and ask: how many protons? How many electrons in a neutral atom?"},"mt_pp9vsZ4wu2":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"An element is in period 2 and group {g}. How many electrons does its atom have?","answer":"2+g","hint":"Period 2 means two shells, and the first one is full.","explain":"The configuration is 2,{g}, so 2 + {g} = {=2+g} electrons.","params":{"g":[1,7]}},{"type":"mc","id":"m2","prompt":"Which configuration is wrong for a neutral atom?","choices":["2,7,1","2,8,1","2,8,8,2"],"answer":0,"hint":"Is any inner shell left with room while an outer one is used?","explain":"2,7,1 leaves room in the second shell while the third is in use. Ten electrons fill as 2,8."},{"type":"mc","id":"m3","prompt":"Why do lithium (2,1) and sodium (2,8,1) react in similar ways?","choices":["Both have one electron in their outer shell","Both have two shells","Both have the same mass"],"answer":0,"hint":"Look at the last number in each configuration.","explain":"Reactions involve the outer electrons. Both have one to lose, so both are in group 1."},{"type":"numeric","id":"m4","prompt":"An element is in period 3 and group {g}. How many electrons does its atom have?","answer":"10+g","hint":"Period 3 means three shells; the first two are full.","explain":"The configuration is 2,8,{g}, so 2 + 8 + {g} = {=10+g}.","params":{"g":[1,7]}},{"type":"mc","id":"m5","prompt":"Oxygen is 2,6. Which statement is true?","choices":["It is in group 6 and period 2","It is in group 2 and period 6","It is in group 8 and period 2"],"answer":0,"hint":"Group: outer electrons. Period: number of shells.","explain":"6 outer electrons gives group 6; 2 shells gives period 2."},{"type":"mc","id":"m6","prompt":"Helium has 2 outer electrons. Why is it in group 0, not group 2?","choices":["Its only shell is full, like the other noble gases","It has no protons","Its outer shell holds 8"],"answer":0,"hint":"How many electrons can the first shell hold?","explain":"The first shell holds only 2, so helium's shell is full. Full outer shells make the unreactive group 0."},{"type":"mc","id":"m7","prompt":"What is the configuration of calcium (20 electrons)?","choices":["2,8,8,2","2,8,10","2,18"],"answer":0,"hint":"The third shell takes 8 here before the fourth starts.","explain":"2 + 8 + 8 = 18, leaving 2 for the fourth shell."}]},"practice":[{"type":"mc","id":"p1","prompt":"What is the electron configuration of magnesium (12 electrons)?","choices":["2,8,2","2,10","8,4","2,2,8"],"answer":0,"hint":"Fill the first shell with 2, the second with up to 8, then carry on.","explain":"2 + 8 = 10, leaving 2 for the third shell: 2,8,2."},{"type":"numeric","id":"p2","prompt":"An atom has the configuration 2,8,{k}. How many electrons does it have?","answer":"10+k","hint":"Add up the electrons in every shell.","explain":"Add the shells: 2 + 8 + {k} = {=10+k} electrons, and a neutral atom has the same number of protons.","params":{"k":[1,8]}},{"type":"numeric","id":"p3","prompt":"An element has the configuration 2,8,{k}. Which group is it in? (Type 0 for group 0.)","answer":"k % 8","hint":"Count the electrons in the outer shell. A full outer shell of 8 means group 0.","explain":"The outer shell holds {k}, so the group is {=k % 8}.","params":{"k":[1,8]}},{"type":"mc","id":"p4","prompt":"Potassium has 19 electrons. Where does the 19th electron go?","choices":["Into a new fourth shell","Into the third shell, which can take up to 18","Into the first shell"],"answer":0,"hint":"Argon, with 18, is 2,8,8.","explain":"For the first 20 elements the third shell holds 8 before the fourth starts, so potassium is 2,8,8,1."}],"explain":{"kid":["Electrons live in shells around the nucleus. Each shell can only hold so many.","The first shell holds 2. The next holds 8. For the first 20 elements, the third holds 8 too.","Electrons fill the inside shell first. Sodium has 11 electrons: 2 in shell one, 8 in shell two, and 1 left over in shell three. We write it 2,8,1.","The last number is the outer shell. Sodium has 1 outer electron, so it sits in group 1. It uses 3 shells, so it is in row 3."],"adult":["In the shell model used up to GCSE, shells fill in order with capacities 2, 8, 8 for the first 20 elements, and the 19th and 20th electrons start a fourth shell. Write the configuration as the counts per shell: chlorine (17) is 2,8,7 and calcium (20) is 2,8,8,2.","The number of occupied shells gives the period. The number of electrons in the outer shell gives the group, except for helium and the noble gases, which have full outer shells and form group 0.","Elements in the same group have the same number of outer electrons, which is why lithium, sodium and potassium react in similar ways: each has one electron to lose.","Common slips: putting the third electron in the first shell, filling the third shell to 18 before starting the fourth, and reading the group from the number of shells. The third shell can hold 18 in fuller models, but for potassium and calcium the fourth shell starts first."]},"familyTip":"Pick a number from 1 to 20 and take turns: one person says the element, the other writes its configuration by filling 2, then 8, then 8. Check together which group it lands in."},"mt_dx_t8RtPt5":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"How many covalent bonds does a hydrogen atom form?","choices":["1","2","7"],"answer":0,"hint":"Hydrogen's only shell is full with 2 electrons.","explain":"It has 1 electron and needs 2, so one shared pair is enough."},{"type":"mc","id":"m2","prompt":"Which pair of elements is most likely to bond covalently?","choices":["Carbon and hydrogen","Sodium and chlorine","Magnesium and oxygen"],"answer":0,"hint":"Covalent bonds usually form between two non-metals.","explain":"Carbon and hydrogen are both non-metals, so they share. The other pairs are a metal with a non-metal, which form ions."},{"type":"numeric","id":"m3","prompt":"{n} carbon atoms are joined in a chain by single bonds. Every other bond goes to a hydrogen atom. How many hydrogen atoms are there?","answer":"2*n+2","hint":"Each carbon makes 4 bonds. The two end carbons use 1 bond on the chain, the middle ones use 2.","explain":"Total carbon bonds 4 × {n}, minus 2 for each of the {=n-1} C–C bonds, leaves {=2*n+2} bonds to hydrogen (methane CH₄, ethane C₂H₆…).","params":{"n":[1,6]}},{"type":"mc","id":"m4","prompt":"Ammonia, NH₃: how many lone pairs does the nitrogen atom have?","choices":["1","0","3"],"answer":0,"hint":"Nitrogen has 5 outer electrons and uses 3 in bonds.","explain":"5 − 3 = 2 unshared electrons, which is one lone pair."},{"type":"numeric","id":"m5","prompt":"A chain of {n} carbon atoms joined by single bonds (C–C–C…) has how many C–C bonds?","answer":"n-1","hint":"Draw 3 carbons in a row and count the links.","explain":"Each bond joins two neighbours, so {n} atoms in a row have {=n-1} bonds between them.","params":{"n":[2,8]}},{"type":"mc","id":"m6","prompt":"Carbon dioxide is O=C=O. How many outer electrons does each oxygen count?","choices":["8","6","10"],"answer":0,"hint":"Each oxygen shares two pairs with carbon.","explain":"6 of its own plus 2 shared from carbon makes 8."},{"type":"mc","id":"m7","prompt":"Nitrogen gas is N₂. Which bond holds the two atoms together?","choices":["A triple bond","A single bond","An ionic bond"],"answer":0,"hint":"Each nitrogen has 5 outer electrons and needs 8.","explain":"Each nitrogen needs 3 more, so they share three pairs: N≡N."}]},"practice":[{"type":"mc","id":"p1","prompt":"What is a covalent bond?","choices":["A shared pair of electrons between two atoms","An electron given from one atom to another","The attraction between two ions of opposite charge"],"answer":0,"hint":"Think about chlorine: neither atom can take an electron from the other.","explain":"Each atom puts one electron into a shared pair. Transferring electrons makes ions, which is ionic bonding."},{"type":"numeric","id":"p2","prompt":"An atom of a non-metal has {v} outer electrons. How many covalent bonds does it usually form?","answer":"8-v","hint":"Each bond adds one shared electron to its count. How many does it need to reach 8?","explain":"8 − {v} = {=8-v} bonds fill its outer shell.","params":{"v":[4,7]}},{"type":"numeric","id":"p3","prompt":"A molecule has {s} single bonds and {d} double bonds. How many electrons are shared in total?","answer":"2*s+4*d","hint":"A single bond is one shared pair; a double bond is two shared pairs.","explain":"{s} × 2 + {d} × 4 = {=2*s+4*d} shared electrons.","params":{"s":[1,4],"d":[0,2]}},{"type":"mc","id":"p4","prompt":"Why does an oxygen molecule, O₂, have a double bond?","choices":["One shared pair leaves each oxygen with only 7, so they share two","Oxygen always gives away 2 electrons","A single bond would give each oxygen 9"],"answer":0,"hint":"Oxygen has 6 outer electrons. Count with one shared pair, then with two.","explain":"6 + 1 = 7 with one pair; 6 + 2 = 8 with two pairs. So O=O."}],"explain":{"kid":["Non-metal atoms want a full outer shell. Two chlorine atoms each have 7 outer electrons and want 8.","Neither one can take an electron from the other. So they share. Each puts in one electron, and the pair counts for both.","That shared pair is a covalent bond. Now both chlorine atoms count 8.","Some atoms share more than one pair. Two oxygen atoms share two pairs. That is a double bond."],"adult":["Covalent bonds form between non-metal atoms. Both atoms attract the shared pair of electrons, and that attraction holds them together. Each atom counts the shared electrons in its own outer shell.","An atom usually forms 8 minus its number of outer electrons bonds: carbon 4, nitrogen 3, oxygen 2, chlorine 1. Hydrogen fills its first shell with 2, so it makes one bond. Unshared outer pairs are called lone pairs.","Two shared pairs make a double bond (O=O, O=C=O) and three a triple bond (N≡N). In dot-and-cross diagrams one atom's electrons are drawn as dots and the other's as crosses, so you can see who gave what.","Common slips: describing a covalent bond as one atom giving an electron to the other (that is ionic bonding, usually metal with non-metal), giving hydrogen 8 outer electrons, and drawing a single bond in O₂ or N₂."]},"familyTip":"Use two hands as atoms and a pair of coins as the shared electrons, held between them. Ask: how many coins does each hand count? Then try water: one hand in the middle sharing with two others."},"mt_TB2zg6ZjHq":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Why does carbon form four covalent bonds?","choices":["It has 4 outer electrons and needs 4 more","It has 4 shells","It has 4 protons"],"answer":0,"hint":"Look at carbon's electron configuration, 2,4.","explain":"Carbon has 4 outer electrons. Sharing 4 pairs gives it 8 in the outer shell, so it makes 4 bonds."},{"type":"numeric","id":"m2","prompt":"How many C–C bonds are in a straight chain of {n} carbon atoms?","answer":"n-1","hint":"Draw a short chain and count the links between neighbours.","explain":"Each link joins two neighbours, so {n} carbons in a line have {=n-1} C–C bonds.","params":{"n":[2,10]}},{"type":"mc","id":"m3","prompt":"Six carbons are joined in a ring. Which formula is right?","choices":["C₆H₁₂","C₆H₁₄","C₆H₂₄"],"answer":0,"hint":"Each carbon in the ring already has two carbon neighbours.","explain":"6 carbons × 2 H = 12. C₆H₁₄ is the open chain, and C₆H₂₄ gives each carbon 4 H."},{"type":"mc","id":"m4","prompt":"Ali draws a carbon atom with five bonds. What is wrong?","choices":["Carbon can only form four bonds","Carbon must form eight bonds","Nothing, carbon can form any number"],"answer":0,"hint":"Count carbon's outer electrons and the bonds they can make.","explain":"Carbon has 4 outer electrons to share, so it forms exactly 4 bonds. A fifth would overfill its outer shell."},{"type":"mc","id":"m5","prompt":"Silicon also has 4 outer electrons. Why are long silicon chains rare?","choices":["Si–Si bonds are much weaker than C–C bonds","Silicon has 8 outer electrons","Silicon cannot share electrons"],"answer":0,"hint":"Carbon chains last because the bond between two carbons is strong.","explain":"Silicon can make 4 bonds, but the Si–Si bond is weak, so silicon chains break apart. Strong C–C bonds let carbon chains grow long."},{"type":"numeric","id":"m6","prompt":"A branched molecule has {n} carbons, single bonds only and no rings. How many hydrogen atoms does it hold?","answer":"2*n+2","hint":"A branch moves a carbon but adds no extra C–C bond. Compare with the straight chain.","explain":"Any chain of {n} carbons, branched or not, has {=n-1} C–C bonds, so it holds 4 × {n} − 2 × {=n-1} = {=2*n+2} H.","params":{"n":[4,9]}},{"type":"mc","id":"m7","prompt":"Which reason best explains why there are millions of carbon compounds?","choices":["Carbon makes four bonds and joins to itself in chains, branches and rings","Carbon is the most common element on Earth","Carbon atoms are very large"],"answer":0,"hint":"Think about what the four bonds and C–C bonds let carbon build.","explain":"Four bonds per atom and strong C–C bonds allow chains, branches and rings of any length. Carbon is not the most common element."},{"type":"mc","id":"m8","prompt":"How many different compounds have the formula C₅H₁₂?","choices":["3","1","5"],"answer":0,"hint":"Try a straight chain, one branch, and a carbon with four carbon neighbours.","explain":"Pentane, methylbutane and dimethylpropane are the three isomers of C₅H₁₂."}]},"practice":[{"type":"numeric","id":"p1","prompt":"A straight chain of {n} carbons is filled with hydrogen. How many hydrogen atoms does it hold?","answer":"2*n+2","hint":"Each end carbon has 3 H. Each carbon in the middle has 2 H.","explain":"2 end carbons × 3 = 6, plus {=n-2} middle carbons × 2 = {=2*n-4}. That makes {=2*n+2}, so the formula is C{n}H{=2*n+2}.","params":{"n":[3,8]}},{"type":"mc","id":"p2","prompt":"How many covalent bonds does a carbon atom form in its compounds?","choices":["4","8","2"],"answer":0,"hint":"Count carbon's outer electrons. Each one is shared in one bond.","explain":"Carbon is 2,4. It shares its 4 outer electrons in 4 bonds, reaching 8. The 8 counts electrons, not bonds."},{"type":"numeric","id":"p3","prompt":"{n} carbons are joined in a ring and filled with hydrogen. How many hydrogen atoms fit?","answer":"2*n","hint":"In a ring every carbon has two carbon neighbours, so each has 2 bonds left.","explain":"{n} carbons × 2 H = {=2*n}. A ring has 2 fewer H than the open chain of {n}, which has {=2*n+2}.","params":{"n":[3,8]}},{"type":"mc","id":"p4","prompt":"Why does neon form no ordinary compounds?","choices":["Its outer shell is already full with 8","It has too few electrons","It is a metal"],"answer":0,"hint":"Bonds form when an atom still needs electrons to fill its outer shell.","explain":"Neon is 2,8. Its outer shell is full, so it has nothing to share and makes no bonds."},{"type":"mc","id":"p5","prompt":"Butane and methylpropane are both C₄H₁₀. What is different about them?","choices":["The order the carbon atoms are joined in","The number of hydrogen atoms","The number of carbon atoms"],"answer":0,"hint":"Same formula means the same number of each atom. Look at the shape.","explain":"Butane is a straight chain; methylpropane has a branch. Same atoms, different structure: they are isomers."}],"explain":{"kid":["A carbon atom has 6 electrons: 2 in the first shell and 4 in the outer shell. It shares those 4 to reach 8. Each shared pair is one bond, so carbon makes four bonds.","Carbon can bond to other carbon atoms. A carbon in a chain uses one bond on each neighbour. The rest of its four bonds can hold hydrogen. Propane, C₃H₈, has 3 carbons and 8 hydrogens.","The chain can branch, too. Butane and methylpropane are both C₄H₁₀, but the atoms are joined in a different order. They are different compounds with the same formula.","The ends of a chain can join to make a ring. Mix chains, branches and rings, and the number of compounds grows very fast. Neon has a full outer shell, so it makes no bonds at all."],"adult":["Carbon's configuration is 2,4. Sharing four electron pairs gives it a full outer shell, so in its compounds carbon nearly always forms four bonds. Nitrogen forms three, oxygen two, and neon, with a full shell already, forms no ordinary compounds.","Two things make carbon special. It has four bonds to spend, so one atom can link to several others at once. And the C–C bond is strong, so long chains are stable. Silicon also forms four bonds, but Si–Si bonds are much weaker, so long silicon chains are rare.","The same formula can describe more than one structure. These are isomers. C₄H₁₀ has 2, C₅H₁₂ has 3, C₁₀H₂₂ has 75 and C₂₀H₄₂ has 366,319. Add rings, double bonds and atoms such as oxygen and nitrogen, and the total runs into many millions.","Common mistakes: saying carbon makes 8 bonds (8 is the electron count, not the bond count); giving each carbon in a chain 4 hydrogens; drawing a carbon with 3 or 5 bonds; and thinking a molecule with the same formula must be the same compound."]},"familyTip":"Use dried pasta pieces as bonds and blobs of modelling clay as atoms. Every carbon blob must hold exactly four pieces. See how many different shapes you can make from 4 carbons and 10 hydrogens. Then try 5 carbons and 12 hydrogens."},"mt_f1w6GDJCnF":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"What is a hydrocarbon?","choices":["A compound of hydrogen and carbon only","Any compound that contains carbon","A compound of hydrogen and oxygen"],"answer":0,"hint":"The name is built from two element names. The key word is only.","explain":"A hydrocarbon contains hydrogen and carbon atoms and nothing else. Many carbon compounds contain other elements too."},{"type":"mc","id":"m2","prompt":"Sam says C₂H₅OH is a hydrocarbon because it contains carbon and hydrogen. What is wrong?","choices":["It also contains oxygen, so it is not carbon and hydrogen only","Nothing, Sam is right","It has too many carbon atoms"],"answer":0,"hint":"Read the formula to the end. Is there a symbol that is not C or H?","explain":"The O in C₂H₅OH is an oxygen atom. A hydrocarbon has C and H only, so ethanol is not one."},{"type":"mc","id":"m3","prompt":"Which of these is NOT a hydrocarbon?","choices":["CH₃Cl","C₆H₆","C₂H₄"],"answer":0,"hint":"Look for a symbol that is neither C nor H.","explain":"CH₃Cl, chloromethane, has a chlorine atom. Benzene, C₆H₆, and ethene, C₂H₄, are carbon and hydrogen only."},{"type":"mc","id":"m4","prompt":"Is carbon dioxide, CO₂, a hydrocarbon?","choices":["No, it has no hydrogen and it contains oxygen","Yes, it contains carbon","Yes, all carbon compounds are hydrocarbons"],"answer":0,"hint":"A hydrocarbon needs both carbon and hydrogen, and nothing else.","explain":"CO₂ has no H at all and has O, so it fails the test twice. Containing carbon is not enough."},{"type":"numeric","id":"m5","prompt":"A list has {n} formulae. {k} of them contain oxygen and the rest contain only carbon and hydrogen. How many are hydrocarbons?","answer":"n-k","hint":"Any formula with oxygen in it fails the test. Take those away from the total.","explain":"The {k} with oxygen are not hydrocarbons, so {n} − {k} = {=n-k} are.","params":{"n":[6,12],"k":[1,5]}},{"type":"mc","id":"m6","prompt":"Cyclohexane, C₆H₁₂, is a ring of six carbons. Is it a hydrocarbon?","choices":["Yes, a ring is fine as long as the atoms are only C and H","No, hydrocarbons must be straight chains","No, rings always contain oxygen"],"answer":0,"hint":"The test is about which elements are present, not the shape.","explain":"Shape does not matter. C₆H₁₂ is carbon and hydrogen only, so it is a hydrocarbon."},{"type":"mc","id":"m7","prompt":"Is hydrogen gas, H₂, a hydrocarbon?","choices":["No, it has no carbon, and it is an element","Yes, it is made of hydrogen","Yes, it burns like methane"],"answer":0,"hint":"Check for both elements in the name hydro-carbon.","explain":"H₂ is the element hydrogen. With no carbon it is not a compound of C and H, so it is not a hydrocarbon."},{"type":"mc","id":"m8","prompt":"Crude oil is mostly a mixture of what?","choices":["Hydrocarbons","Carbohydrates such as glucose","Carbon dioxide and water"],"answer":0,"hint":"Petrol, diesel and the gas in a camping stove all come from it.","explain":"Crude oil is mostly hydrocarbons of many sizes. Carbohydrates such as glucose contain oxygen, so they are not hydrocarbons."},{"type":"numeric","id":"m9","prompt":"Propane, C₃H₈, is a hydrocarbon. How many atoms are there in {n} molecules of propane?","answer":"11*n","hint":"Read the formula: 3 carbon atoms and 8 hydrogen atoms in each molecule, and nothing else.","explain":"Each molecule has 3 + 8 = 11 atoms, so {n} molecules have 11 × {n} = {=11*n} atoms.","params":{"n":[2,9]}}]},"practice":[{"type":"mc","id":"p1","prompt":"Which of these is a hydrocarbon?","choices":["C₃H₈","C₂H₅OH","CO₂"],"answer":0,"hint":"List the element symbols in each formula. Which list is only C and H?","explain":"C₃H₈, propane, has only C and H. C₂H₅OH also has O, and CO₂ has no H."},{"type":"numeric","id":"p2","prompt":"A list has {n} formulae. {a} of them contain only C and H. Each of the rest also contains O or Cl. How many are NOT hydrocarbons?","answer":"n-a","hint":"One extra element is enough to fail the test. Count the formulae that are not C and H only.","explain":"Only the {a} with C and H alone are hydrocarbons, so {n} − {a} = {=n-a} are not.","params":{"n":[8,12],"a":[1,7]}},{"type":"numeric","id":"p3","prompt":"A hydrocarbon has {c} carbon atoms and {h} hydrogen atoms in each molecule. How many atoms are in one molecule?","answer":"c+h","hint":"A hydrocarbon has only two kinds of atom. Add the two counts.","explain":"Carbon and hydrogen are the only atoms, so {c} + {h} = {=c+h} atoms in one molecule.","params":{"c":[1,8],"h":[4,18]}},{"type":"mc","id":"p4","prompt":"Propene, C₃H₆, has a C=C double bond. Is it a hydrocarbon?","choices":["Yes, its atoms are only carbon and hydrogen","No, hydrocarbons have only single bonds","No, it has too few hydrogen atoms"],"answer":0,"hint":"The definition is about which kinds of atom are present, not how they are bonded.","explain":"Only the elements matter. C₃H₆ is carbon and hydrogen only, so it is a hydrocarbon, double bond and all."},{"type":"mc","id":"p5","prompt":"Why is glucose, C₆H₁₂O₆, not a hydrocarbon?","choices":["It contains oxygen as well as carbon and hydrogen","It is too big a molecule","It has no carbon atoms"],"answer":0,"hint":"Read every element symbol in the formula, not just the first two.","explain":"Glucose has 6 O atoms. Any element besides C and H means it is not a hydrocarbon, whatever its size."}],"explain":{"kid":["A hydrocarbon is made of just two kinds of atom: hydrogen and carbon. The name tells you: hydro for hydrogen, carbon for carbon.","Methane, CH₄, is a hydrocarbon. Its formula has only C and H in it. Octane, C₈H₁₈, is one too. It is in petrol.","Ethanol, C₂H₅OH, has C and H, but it also has an O. That one oxygen atom means it is not a hydrocarbon. The key word is only.","A compound needs both C and H to count. CO₂ has no H. H₂ has no C. Neither of them is a hydrocarbon."],"adult":["A hydrocarbon is a compound that contains carbon and hydrogen atoms and nothing else. To test a formula, list its element symbols. If the list is exactly C and H, it is a hydrocarbon.","The test ignores size and shape. Methane, CH₄, and octane, C₈H₁₈, are hydrocarbons. So are propene, C₃H₆, which has a C=C double bond, and benzene, C₆H₆, a ring. Crude oil is mostly a mixture of hydrocarbons.","Many carbon compounds are not hydrocarbons. Ethanol, C₂H₅OH, and glucose, C₆H₁₂O₆, contain oxygen. Chloromethane, CH₃Cl, contains chlorine. Carbon dioxide, CO₂, has no hydrogen at all.","Common mistakes: calling any compound with C and H a hydrocarbon and forgetting the word only; thinking a double bond or a ring rules a molecule out; and treating every carbon compound, or hydrogen gas, H₂, as a hydrocarbon."]},"familyTip":"Read the ingredients or chemical names on a few labels at home, such as a gas bottle (propane or butane), a candle, nail polish remover (propanone) or vinegar (ethanoic acid). Look up each formula and decide together: only C and H, or something else too?"},"mt_UJ2KVmA1tf":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which is the structural formula of butane?","choices":["CH₃CH₂CH₂CH₃","C₄H₁₀","CH₃CH₃CH₃CH₃"],"answer":0,"hint":"The end carbons have one carbon neighbour; the middle ones have two.","explain":"End carbons are CH₃ and middle carbons are CH₂. C₄H₁₀ is the molecular formula, and CH₃ in the middle would give those carbons five bonds."},{"type":"mc","id":"m2","prompt":"Butane and methylpropane are both C₄H₁₀. Which statement is true?","choices":["They have different structural formulae","They are the same molecule","They have different numbers of atoms"],"answer":0,"hint":"The molecular formula counts atoms; it does not show how they are joined.","explain":"Butane is CH₃CH₂CH₂CH₃ and methylpropane is CH₃CH(CH₃)CH₃: same atoms, joined differently."},{"type":"mc","id":"m3","prompt":"Mia says the molecular formula of ethane is CH₃. What is wrong?","choices":["CH₃ is only one group; ethane has two carbons, C₂H₆","Nothing, CH₃ is right","Ethane has three carbons"],"answer":0,"hint":"Ethane's structural formula is CH₃CH₃. Add up both groups.","explain":"Ethane is CH₃CH₃: two CH₃ groups. Together that is 2 C and 6 H, so C₂H₆."},{"type":"numeric","id":"m4","prompt":"The structural formula of a straight chain of {n} carbons is written CH₃CH₂…CH₃. How many CH₂ groups does it contain?","answer":"n-2","hint":"The two end carbons have one carbon neighbour each, so they are CH₃. Every other carbon is CH₂.","explain":"2 of the {n} carbons are CH₃ ends, so {n} − 2 = {=n-2} are CH₂ groups in the middle.","params":{"n":[3,10]}},{"type":"numeric","id":"m5","prompt":"How many H atoms are in the molecular formula of CH₃(CH₂){k}OH?","answer":"2*k+4","hint":"Add the H in CH₃, in each CH₂, and the one in OH.","explain":"3 + 2 × {k} + 1 = {=2*k+4} H. The molecular formula is C{=k+1}H{=2*k+4}O.","params":{"k":[1,5]}},{"type":"mc","id":"m6","prompt":"What is the molecular formula of chloroethane, CH₃CH₂Cl?","choices":["C₂H₅Cl","C₂H₆Cl","CH₅Cl"],"answer":0,"hint":"Cl takes the place of one H. Count the H in CH₃ and CH₂ only.","explain":"3 + 2 = 5 H, 2 C and 1 Cl: C₂H₅Cl."},{"type":"mc","id":"m7","prompt":"Which structural formula matches a chain of three carbons with a CH₃ branch on the middle carbon?","choices":["CH₃CH(CH₃)CH₃","CH₃CH₂CH₂CH₃","CH₃CH₂(CH₃)CH₃"],"answer":0,"hint":"The middle carbon bonds to three carbons, so it keeps only one H. The branch goes in brackets after it.","explain":"The middle carbon has 3 carbon neighbours and 1 H, so it is CH, followed by the branch (CH₃): CH₃CH(CH₃)CH₃."},{"type":"mc","id":"m8","prompt":"In a correct displayed formula, how many lines meet at each carbon atom?","choices":["4","3","It depends on the H count only"],"answer":0,"hint":"Carbon makes four covalent bonds, and each bond is one line.","explain":"Every carbon has four bonds, so four lines. A double bond counts as two of them."}]},"practice":[{"type":"mc","id":"p1","prompt":"What is the molecular formula of CH₃CH₂CH₃?","choices":["C₃H₈","C₃H₇","CH₈"],"answer":0,"hint":"Count the carbons, then add up the H in every group.","explain":"3 carbons, and 3 + 2 + 3 = 8 hydrogens, so C₃H₈."},{"type":"numeric","id":"p2","prompt":"A straight chain is written CH₃(CH₂){k}CH₃, which means {k} CH₂ groups in the middle. How many H atoms are in its molecular formula?","answer":"2*k+6","hint":"Each end group CH₃ has 3 H. Each CH₂ in the middle has 2 H.","explain":"3 + 3 = 6 H on the ends, plus 2 × {k} = {=2*k} H in the middle: {=2*k+6} H in all, so C{=k+2}H{=2*k+6}.","params":{"k":[1,6]}},{"type":"numeric","id":"p3","prompt":"A displayed formula shows a straight chain of {n} carbons with H on every free bond. How many lines (bonds) are in the drawing altogether?","answer":"3*n+1","hint":"Count the C–C lines and the C–H lines separately. The chain holds 2n + 2 H.","explain":"There are {=n-1} C–C lines and {=2*n+2} C–H lines: {=n-1} + {=2*n+2} = {=3*n+1} lines.","params":{"n":[2,7]}},{"type":"mc","id":"p4","prompt":"What does a displayed formula show that a molecular formula does not?","choices":["How the atoms are joined, with every bond","How many carbon atoms there are","Which elements are present"],"answer":0,"hint":"Both tell you how many atoms of each kind. Only one tells you which atom is joined to which.","explain":"A molecular formula only counts atoms. The displayed formula shows every bond, so you can see the shape of the chain."},{"type":"mc","id":"p5","prompt":"What is the molecular formula of ethanol, CH₃CH₂OH?","choices":["C₂H₆O","C₂H₅O","C₂H₆"],"answer":0,"hint":"Count every H, including the one on the oxygen.","explain":"3 + 2 + 1 = 6 H, plus 2 C and 1 O, gives C₂H₆O. C₂H₅O misses the H in OH."}],"explain":{"kid":["A displayed formula is a drawing. It shows every atom as a letter and every bond as a line. Each carbon has four lines.","A structural formula goes along the chain one carbon at a time. You write each carbon with the H atoms joined to it. Propane is CH₃CH₂CH₃.","A molecular formula just counts. Add up each kind of atom and write C first, then H. Propane is C₃H₈.","Two molecules can share a molecular formula but have different shapes. Butane and methylpropane are both C₄H₁₀. Their drawings and structural formulae are not the same."],"adult":["A displayed formula shows every atom and every bond. Each bond is a line, so you can check that each carbon has four. It shows which atoms are joined, not the real 3D angles.","A structural formula writes each carbon with its own H atoms, in chain order. Ethane is CH₃CH₃, propane is CH₃CH₂CH₃ and ethanol is CH₃CH₂OH. A branch goes in brackets after the carbon it hangs from: methylpropane is CH₃CH(CH₃)CH₃.","A molecular formula gives the total of each atom. Carbon comes first, then hydrogen, then the rest in A to Z order: C₂H₆, C₃H₈, C₂H₆O. It says nothing about shape, so butane and methylpropane share C₄H₁₀.","Common mistakes: drawing a carbon with three or five bonds; writing one group, such as CH₃, as the formula for ethane; missing the H in an OH group when you count; and thinking that one molecular formula means one molecule."]},"familyTip":"Write CH₃, CH₂ and OH on small cards. Lay them in a row to build CH₃CH₂CH₃ or CH₃CH₂OH, then count the atoms together to get the molecular formula. Finally, draw it out with a line for every bond and check that each C has four lines."},"mt_djL0kvgJ07":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"What is the general formula of the alkanes?","choices":["CₙH₂ₙ₊₂","CₙH₂ₙ","CₙH₄ₙ"],"answer":0,"hint":"Methane is CH₄ and ethane is C₂H₆. Which formula gives both?","explain":"CₙH₂ₙ₊₂: n = 1 gives CH₄ and n = 2 gives C₂H₆. CₙH₂ₙ is the alkene formula, and CₙH₄ₙ ignores the C–C bonds."},{"type":"mc","id":"m2","prompt":"What is the formula of butane?","choices":["C₄H₁₀","C₄H₈","C₄H₁₆"],"answer":0,"hint":"But- means 4 carbons. Use 2 × 4 + 2.","explain":"Butane has 4 carbons and 2 × 4 + 2 = 10 hydrogens: C₄H₁₀. C₄H₈ forgets the ends, and C₄H₁₆ gives every carbon four H."},{"type":"mc","id":"m3","prompt":"Ali says each carbon in ethane has four hydrogens, so ethane is C₂H₈. What is the slip?","choices":["One bond on each carbon joins the two carbons, so each has only 3 H","Nothing, Ali is right","Ethane has 3 carbons"],"answer":0,"hint":"Count the bonds on one carbon in ethane, including the bond to the other carbon.","explain":"Each carbon makes four bonds, but one is the C–C bond. That leaves 3 H on each carbon, so ethane is C₂H₆."},{"type":"mc","id":"m4","prompt":"Propene, C₃H₆, is a hydrocarbon. Why is it not an alkane?","choices":["It has a C=C double bond, so it is unsaturated and does not fit CₙH₂ₙ₊₂","It contains oxygen","It has too many carbon atoms"],"answer":0,"hint":"Compare its hydrogen count with 2 × 3 + 2.","explain":"An alkane with 3 carbons has 8 H. Propene has 6, because its C=C double bond uses two bonds that could hold H. It is an alkene."},{"type":"numeric","id":"m5","prompt":"How many hydrogen atoms are in one molecule of the alkane with {n} carbon atoms?","answer":"2*n+2","hint":"Two hydrogens for each carbon, plus two for the ends of the chain.","explain":"2 × {n} + 2 = {=2*n+2} hydrogen atoms, so the formula is C{n}H{=2*n+2}.","params":{"n":[3,15]}},{"type":"numeric","id":"m6","prompt":"How many atoms in total are in one molecule of the alkane with {n} carbon atoms?","answer":"3*n+2","hint":"Find the hydrogens with 2n + 2, then add the carbons as well.","explain":"{n} carbons + {=2*n+2} hydrogens = {=3*n+2} atoms in each molecule.","params":{"n":[1,10]}},{"type":"mc","id":"m7","prompt":"What kind of bonds are found between the carbon atoms in an alkane?","choices":["Single covalent bonds only","At least one double bond","Ionic bonds"],"answer":0,"hint":"Alkanes are saturated. What would a double bond do to the hydrogen count?","explain":"Every C–C bond in an alkane is a single covalent bond. A C=C double bond would make it an alkene instead."},{"type":"mc","id":"m8","prompt":"Which alkane has 3 carbon atoms?","choices":["Propane","Butane","Ethane"],"answer":0,"hint":"The stems go meth- (1), eth- (2), prop- (3), but- (4).","explain":"Prop- means 3 carbons, so propane, C₃H₈. Ethane has 2 carbons and butane has 4."},{"type":"numeric","id":"m9","prompt":"An alkane has {=2*n+2} hydrogen atoms in each molecule. How many carbon atoms does it have?","answer":"n","hint":"Subtract the 2 end hydrogens first, then halve what is left.","explain":"({=2*n+2} − 2) ÷ 2 = {n} carbon atoms.","params":{"n":[3,12]}}]},"practice":[{"type":"numeric","id":"p1","prompt":"An alkane has {n} carbon atoms. How many hydrogen atoms does each molecule have?","answer":"2*n+2","hint":"Use CₙH₂ₙ₊₂: double the number of carbons, then add 2 for the two ends.","explain":"2 × {n} + 2 = {=2*n+2}. Each carbon holds 2 H, and the two end carbons hold 1 extra H each.","params":{"n":[2,12]}},{"type":"mc","id":"p2","prompt":"Which of these formulae is an alkane?","choices":["C₃H₈","C₃H₆","C₃H₇OH"],"answer":0,"hint":"An alkane has only C and H, and fits CₙH₂ₙ₊₂. Try n = 3.","explain":"With 3 carbons an alkane has 2 × 3 + 2 = 8 hydrogens, so C₃H₈, propane. C₃H₆ is 2 short, and C₃H₇OH contains oxygen."},{"type":"numeric","id":"p3","prompt":"An alkane molecule has {=2*n+2} hydrogen atoms. How many carbon atoms does it have?","answer":"n","hint":"Undo CₙH₂ₙ₊₂ step by step: take away the 2 end hydrogens, then halve.","explain":"({=2*n+2} − 2) ÷ 2 = {n}. The alkane is C{n}H{=2*n+2} with {n} carbons.","params":{"n":[2,10]}},{"type":"mc","id":"p4","prompt":"Why is propane, C₃H₈, called saturated?","choices":["Every carbon already has four bonds, so no more hydrogen can be added","It is dissolved in water","It has a double bond between two carbons"],"answer":0,"hint":"Think about whether any carbon in the chain has a free bond left over.","explain":"All its bonds are single and every carbon has four bonds, so it holds as much hydrogen as it can. A double bond would make it unsaturated."},{"type":"numeric","id":"p5","prompt":"In a straight-chain alkane with {n} carbons, how many hydrogen atoms sit on the middle carbons (all the carbons except the two ends)?","answer":"2*(n-2)","hint":"There are {n} − 2 middle carbons. Each one uses 2 bonds for its neighbours, leaving 2 for hydrogen.","explain":"{n} − 2 = {=n-2} middle carbons, each with 2 H, gives {=2*(n-2)} hydrogens. The two ends add 3 + 3 = 6 more.","params":{"n":[3,10]}}],"explain":{"kid":["Alkanes are a family of molecules made of carbon and hydrogen. The carbons join up in a chain. Every bond is a single bond.","Each carbon makes four bonds. A carbon in the middle of the chain uses two of them to hold its neighbours. That leaves room for two H. A carbon at an end has one neighbour, so it holds three H.","So the count goes like this. Two H for every carbon, then two more for the ends. Butane has 4 carbons, so it has 2 × 4 + 2 = 10 hydrogens. Its formula is C₄H₁₀.","No carbon in an alkane has a spare bond. You cannot fit in one more H. We say alkanes are saturated: they are full of hydrogen."],"adult":["Alkanes are a family of hydrocarbons in which every bond between carbon atoms is a single covalent bond. The first four are methane, CH₄; ethane, C₂H₆; propane, C₃H₈; and butane, C₄H₁₀. The name ending -ane marks an alkane, and the stem meth-, eth-, prop- or but- gives the number of carbons.","Each carbon forms four bonds. In a straight chain of n carbons, n − 1 bonds link carbon to carbon. The end carbons carry three hydrogens each and the middle ones carry two. That gives the general formula CₙH₂ₙ₊₂: two hydrogens per carbon plus one extra at each end.","Alkanes are saturated. Every carbon already has its four bonds, so no more hydrogen can be added. A hydrocarbon with a C=C double bond has two fewer hydrogens, CₙH₂ₙ, and is unsaturated. Propene, C₃H₆, is an alkene, not an alkane.","Common mistakes: writing CₙH₂ₙ and forgetting the two end hydrogens; giving each carbon four hydrogens, which ignores the C–C bonds; and calling any hydrocarbon an alkane, even one with a double bond. Smaller alkanes such as propane and butane are gases used as fuels."]},"familyTip":"Look at a camping gas canister or a lighter refill: many say propane or butane. Work out each formula together from the number of carbons (prop- is 3, but- is 4) using two hydrogens per carbon plus two, then check: C₃H₈ and C₄H₁₀."},"mt_ofQRMhETTm":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"What decides which homologous series a compound belongs to?","choices":["Its functional group","Its number of carbon atoms","Its boiling point"],"answer":0,"hint":"Which part of the molecule decides how it reacts?","explain":"The functional group, such as –OH or C=C, defines the family. Compounds with the same number of carbons can be in different series."},{"type":"mc","id":"m2","prompt":"Propene, C₃H₆, is an alkene. What is the next alkene in the series?","choices":["C₄H₈","C₄H₉","C₄H₁₀"],"answer":0,"hint":"Add one CH₂ to C₃H₆: one more C and two more H.","explain":"C₃H₆ + CH₂ = C₄H₈, butene. C₄H₁₀ has no C=C, so it is an alkane."},{"type":"mc","id":"m3","prompt":"Butane boils at −1 °C and hexane at 69 °C. Which is the best estimate for pentane, the alkane between them?","choices":["About 36 °C","About −40 °C","About 120 °C"],"answer":0,"hint":"Boiling point changes gradually along a series. Pentane sits between butane and hexane.","explain":"Pentane must boil between −1 °C and 69 °C; it boils at 36 °C. The trend is gradual, so the middle member lands in between."},{"type":"mc","id":"m4","prompt":"Mia says CH₃OH and C₃H₇OH cannot be in the same series because they are not next to each other. What is wrong?","choices":["They differ by 2 × CH₂ and both have –OH, so they are in the same series","Nothing, Mia is right","They have different numbers of oxygen atoms"],"answer":0,"hint":"A series is a whole family, not just a pair of neighbours.","explain":"Methanol and propanol are both alcohols. They differ by C₂H₄, which is two CH₂ steps, so they sit two places apart in one series."},{"type":"numeric","id":"m5","prompt":"An alcohol has {n} carbon atoms. Using CₙH₂ₙ₊₁OH, how many hydrogen atoms does one molecule contain in total?","answer":"2*n+2","hint":"Count the hydrogens on the carbon chain, then remember the H in the –OH group.","explain":"2 × {n} + 1 = {=2*n+1} H on the carbons, plus 1 in –OH, gives {=2*n+2} hydrogen atoms.","params":{"n":[1,8]}},{"type":"numeric","id":"m6","prompt":"The alkenes fit CₙH₂ₙ. How many hydrogen atoms are in the alkene with {n} carbon atoms?","answer":"2*n","hint":"Put n = {n} into CₙH₂ₙ: the H count is twice the C count.","explain":"2 × {n} = {=2*n}, so the alkene is C{n}H{=2*n}.","params":{"n":[2,10]}},{"type":"mc","id":"m7","prompt":"Why do all the alcohols react with sodium in a similar way?","choices":["They all have the same functional group, –OH","They all have the same boiling point","They all have exactly two carbon atoms"],"answer":0,"hint":"The part of the molecule that reacts is the same in every member.","explain":"Every alcohol carries –OH, and that group does the reacting, so the reactions are similar even though chain lengths differ."},{"type":"mc","id":"m8","prompt":"Which pair is NOT in the same homologous series?","choices":["C₂H₄ and C₂H₆","CH₄ and C₃H₈","C₂H₅OH and C₄H₉OH"],"answer":0,"hint":"Same carbons does not mean same family. Check the general formula of each.","explain":"C₂H₄ is an alkene (CₙH₂ₙ) and C₂H₆ is an alkane (CₙH₂ₙ₊₂). The other pairs share a formula and differ by CH₂ steps."}]},"practice":[{"type":"mc","id":"p1","prompt":"Two neighbouring members of a homologous series differ by what?","choices":["CH₂","CH₃","One carbon atom only"],"answer":0,"hint":"Compare CH₄ with C₂H₆: count the extra carbons and the extra hydrogens.","explain":"CH₄ to C₂H₆ adds 1 C and 2 H, which is CH₂. Every neighbouring pair in a series differs by exactly this."},{"type":"numeric","id":"p2","prompt":"In a homologous series, one member has {a} carbon atoms. How many CH₂ units must be added to reach the member with {b} carbon atoms?","answer":"b-a","hint":"Each CH₂ unit adds exactly one carbon atom. Count the extra carbons.","explain":"{b} − {a} = {=b-a} extra carbons, so {=b-a} CH₂ units.","params":{"a":[1,4],"b":[5,9]}},{"type":"numeric","id":"p3","prompt":"A CH₂ unit has a relative mass of 14. Two members of the same series differ by {k} CH₂ units. How much larger is the relative formula mass of the bigger one?","answer":"14*k","hint":"Each CH₂ adds 12 for the carbon and 2 for the hydrogens.","explain":"{k} × 14 = {=14*k}, so the bigger molecule is {=14*k} heavier.","params":{"k":[1,6]}},{"type":"mc","id":"p4","prompt":"Which compound is in the same homologous series as ethanol, C₂H₅OH?","choices":["C₃H₇OH","C₂H₆","CH₃COOH"],"answer":0,"hint":"Look for the same functional group, not the same number of carbons.","explain":"C₃H₇OH, propanol, has –OH and is one CH₂ bigger. C₂H₆ has no –OH, and CH₃COOH has –COOH, a different group."},{"type":"mc","id":"p5","prompt":"Which statement about the members of a homologous series is true?","choices":["They react in similar ways, and their boiling points change gradually","They all have the same boiling point","They all have the same number of carbon atoms"],"answer":0,"hint":"Think about what the shared functional group controls, and what changes as the chain grows.","explain":"The shared group gives similar reactions. Boiling point rises steadily with chain length, and the carbon count changes by one each step."}],"explain":{"kid":["Organic compounds come in families. Chemists call each family a homologous series. Alkanes are one family. Alcohols are another.","Members of a family are like steps on a ladder. Each step adds one more CH₂: one carbon and two hydrogens. Methanol is CH₃OH. Ethanol is C₂H₅OH. Propanol is C₃H₇OH.","What makes a family is a special group of atoms called the functional group. Every alcohol has an OH group. Every alkene has a C=C bond. The group is the part that reacts, so members of a family react in a similar way.","They are not all the same, though. Bigger members boil at higher temperatures. Each step up the ladder makes the boiling point rise a bit more."],"adult":["A homologous series is a family of organic compounds. All its members share a functional group and one general formula. Four examples are the alkanes, CₙH₂ₙ₊₂, the alkenes, CₙH₂ₙ, the alcohols, CₙH₂ₙ₊₁OH, and the carboxylic acids.","Each member differs from the next by one CH₂ unit. Going from ethanol, C₂H₅OH, to propanol, C₃H₇OH, adds one carbon and two hydrogens, and the –OH stays. That steady step is why one formula covers the whole family.","The functional group is the atom or group of atoms that decides how a compound reacts. All alcohols burn and react with sodium because they all carry –OH. Physical properties change step by step instead: boiling point rises as the chain grows, from −162 °C for methane to 36 °C for pentane.","Common mistakes: thinking neighbours differ by CH₃; putting two compounds in one series because they have the same number of carbons, such as ethane and ethanol; and expecting members to have identical properties when only their reactions are alike."]},"familyTip":"Find two or three products at home that list an alcohol, such as hand gel (ethanol) or some cleaners (propanol). Write their formulae on a strip of paper as a ladder: CH₃OH, C₂H₅OH, C₃H₇OH. Ask each other what is added at every step and what never changes."},"mt_pe4Ehc0koq":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"An atom has the electron arrangement 2, 8, 5. Where is it in the periodic table?","choices":["Group 5, Period 3","Group 3, Period 5","Group 15, Period 3"],"answer":0,"hint":"Count the shells for the period, then read the last number for the group.","explain":"Three numbers means three shells, so Period 3. The outer shell holds 5, so Group 5. This is phosphorus."},{"type":"mc","id":"m2","prompt":"An element is in Group 7, Period 2. How many outer electrons and shells does it have?","choices":["7 outer electrons and 2 shells","2 outer electrons and 7 shells","9 outer electrons and 2 shells"],"answer":0,"hint":"The group gives one number and the period gives the other. Do not swap them.","explain":"Group 7 means 7 outer electrons, and Period 2 means 2 shells: the arrangement 2, 7, which is fluorine."},{"type":"mc","id":"m3","prompt":"Sam says sodium and chlorine should react in the same way because both are in Period 3. What is wrong?","choices":["Reactions follow the group, and they have different numbers of outer electrons","Nothing, Sam is right","They are in different periods"],"answer":0,"hint":"What do elements in the same period share, and what do they not share?","explain":"Both have three shells, but sodium has 1 outer electron and chlorine has 7. Outer electrons decide how an element reacts, so they behave very differently."},{"type":"numeric","id":"m4","prompt":"An element in Period 3 has the atomic number {z}. Which group is it in?","answer":"z-10","hint":"Period 3 means three shells. Fill 2 and then 8, and see how many electrons are left for the outer shell.","explain":"The arrangement is 2, 8, {=z-10}. That leaves {=z-10} outer electrons, so it is in Group {=z-10}.","params":{"z":[11,17]}},{"type":"numeric","id":"m5","prompt":"An atom has {n} electrons in its outer shell and is in Groups 1 to 7. What is its group number?","answer":"n","hint":"For the main groups, the group number and the outer-shell electrons match.","explain":"{n} outer electrons puts the element in Group {n}.","params":{"n":[1,7]}},{"type":"mc","id":"m6","prompt":"Helium has only 2 electrons. Why is it placed in Group 0 and not Group 2?","choices":["Its only shell is full, like the other noble gases","It has no outer electrons","It has 8 outer electrons"],"answer":0,"hint":"How many electrons can the first shell hold?","explain":"The first shell holds at most 2, so helium's outer shell is full. Like neon and argon, it barely reacts, so it belongs with Group 0."},{"type":"mc","id":"m7","prompt":"Potassium is below sodium in Group 1. How does potassium react with water?","choices":["Like sodium, but more vigorously","It does not react, because it is a different element","Slowly, like magnesium"],"answer":0,"hint":"Same group means a similar reaction. What is the trend down Group 1?","explain":"Both have 1 outer electron, so both fizz and make hydrogen. Reactivity rises down Group 1, so potassium reacts more strongly and the hydrogen catches fire."},{"type":"mc","id":"m8","prompt":"What do all the elements in Period 2 have in common?","choices":["They all have two occupied electron shells","They all have two outer electrons","They all react in the same way"],"answer":0,"hint":"Lithium is 2, 1 and neon is 2, 8. What is the same about both?","explain":"Every Period 2 atom has electrons in two shells. The number of outer electrons rises from 1 to 8 across the row, so their reactions differ."}]},"practice":[{"type":"mc","id":"p1","prompt":"What does the period number of an element tell you about its atoms?","choices":["The number of occupied electron shells","The number of outer-shell electrons","The total number of electrons"],"answer":0,"hint":"Think about sodium, 2, 8, 1. It is in Period 3. What is there three of?","explain":"Sodium has electrons in three shells and sits in Period 3. The period number counts the occupied shells."},{"type":"numeric","id":"p2","prompt":"An element in Period 3 has {g} electrons in its outer shell. How many electrons does one of its atoms have in total?","answer":"10+g","hint":"Period 3 means three shells. The first two shells are full with 2 and 8 electrons.","explain":"The arrangement is 2, 8, {g}, so the total is 2 + 8 + {g} = {=10+g} electrons.","params":{"g":[1,7]}},{"type":"numeric","id":"p3","prompt":"An element is in Group {g}, Period 2. What is its atomic number?","answer":"2+g","hint":"Period 2 means two shells. The first shell is full with 2. The group tells you the outer shell.","explain":"The arrangement is 2, {g}, which is {=2+g} electrons. A neutral atom has as many protons as electrons, so the atomic number is {=2+g}.","params":{"g":[1,7]}},{"type":"mc","id":"p4","prompt":"Which element will react most like sodium?","choices":["Potassium, in Group 1","Magnesium, next to sodium in Period 3","Neon, which has one electron fewer"],"answer":0,"hint":"Reactions depend on outer electrons. Which element also has exactly one outer electron?","explain":"Potassium is in Group 1 with sodium, so both have 1 outer electron and react in similar ways. Magnesium has 2 outer electrons and neon has a full outer shell."},{"type":"mc","id":"p5","prompt":"Why are the Group 0 elements so unreactive?","choices":["Their outer shells are already full","They have no electrons in their outer shell","They have only one shell each"],"answer":0,"hint":"Look at neon, 2, 8, and argon, 2, 8, 8. How full is the last shell?","explain":"Each noble gas has a full outer shell, so it has no need to gain, lose or share electrons. Only helium has just one shell."}],"explain":{"kid":["The periodic table is not a random list. Where an element sits tells you how its electrons are arranged.","Each row is called a period. Count the rows from the top. The row number is how many shells of electrons the atom has. Sodium has three shells, so it is in Period 3.","Each column is called a group. For Groups 1 to 7, the group number is how many electrons are in the outer shell. Sodium has one outer electron, so it is in Group 1.","Elements in the same group act alike, because the outer electrons do the reacting. Lithium, sodium and potassium all fizz in water. The last column is Group 0. Its atoms have full outer shells, so they hardly react at all."],"adult":["Mendeleev ordered the elements by their properties before electrons were known. The electron model now explains why his table works. Each row is a period, and an atom's period number equals its number of occupied shells.","Each column is a group. For the main groups, 1 to 7, the group number equals the number of electrons in the outer shell. Chlorine is 2, 8, 7: three shells, so Period 3, and seven outer electrons, so Group 7.","Reactions involve the outer electrons, so elements in a group react in similar ways. All Group 1 metals react with water to form hydrogen and an alkaline solution. Properties still change gradually down a group: Group 1 metals get more reactive, while Group 7 elements get less reactive. Group 0, the noble gases, have full outer shells and are very unreactive.","Common mistakes: swapping the two rules, so that the group gives the shells; using the total number of electrons instead of the outer ones; and expecting elements in the same period to behave alike. Helium is a careful exception: it is in Group 0 with only 2 outer electrons, because its single shell is full."]},"familyTip":"Draw a 4 by 8 grid on paper. Take turns saying an electron arrangement, such as 2, 8, 3, and racing to point at the box where it belongs. Then ask which element in the grid would react most like it."},"mt_YHKhUliaQh":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"You are shown C₃H₈ and C₃H₆. Which one is an alkene?","choices":["C₃H₆","C₃H₈","Both, as they have 3 carbons"],"answer":0,"hint":"For 3 carbons, an alkene has 2 × 3 hydrogens.","explain":"C₃H₆ fits CₙH₂ₙ, so it is propene. C₃H₈ fits CₙH₂ₙ₊₂, so it is propane, an alkane."},{"type":"mc","id":"m2","prompt":"Which is the correct displayed structure of propene, written in short?","choices":["CH₂=CH–CH₃","CH₃=CH–CH₃","CH₂=CH₂–CH₃"],"answer":0,"hint":"Every carbon needs exactly four bonds. The double bond counts as two.","explain":"In CH₂=CH–CH₃ each carbon has four bonds. CH₃= would give the first carbon five bonds, and =CH₂– would give the middle carbon five."},{"type":"mc","id":"m3","prompt":"Orange bromine water is shaken with a hydrocarbon and turns colourless. What does this show?","choices":["The hydrocarbon has a C=C double bond","The hydrocarbon is an alkane","The hydrocarbon has no hydrogen"],"answer":0,"hint":"Which kind of hydrocarbon can add bromine atoms?","explain":"Bromine adds across a C=C, which removes its colour. Alkanes have no double bond, so they leave bromine water orange."},{"type":"numeric","id":"m4","prompt":"An alkene has {=2*n} hydrogen atoms. How many carbon atoms does it have?","answer":"n","hint":"In CₙH₂ₙ the hydrogens are twice the carbons, so work backwards.","explain":"{=2*n} ÷ 2 = {n}, so the alkene is C{n}H{=2*n}.","params":{"n":[2,8]}},{"type":"numeric","id":"m5","prompt":"A molecule of an alkene with {n} carbons reacts with bromine, Br₂. How many atoms does the product molecule contain in total?","answer":"3*n+2","hint":"Count the carbons and hydrogens of CₙH₂ₙ, then add the two bromine atoms that join across the C=C.","explain":"{n} C + {=2*n} H + 2 Br = {=3*n+2} atoms, for example C₂H₄Br₂ for ethene.","params":{"n":[2,6]}},{"type":"mc","id":"m6","prompt":"In ethene, how many hydrogen atoms are bonded to each carbon?","choices":["2","3","1"],"answer":0,"hint":"Each carbon makes 4 bonds, and 2 of them are in the C=C.","explain":"4 − 2 = 2, so each carbon holds 2 H: CH₂=CH₂, which is C₂H₄."},{"type":"mc","id":"m7","prompt":"Leo says alkanes are unsaturated because they have lots of hydrogen. What is wrong?","choices":["Alkanes are saturated: every carbon already has four single bonds","Nothing, Leo is right","Alkanes have no hydrogen at all"],"answer":0,"hint":"Saturated means no more atoms can be added. Can more be added to an alkane?","explain":"In an alkane every carbon already has four single bonds, so nothing more can add. That makes alkanes saturated, and alkenes unsaturated."},{"type":"mc","id":"m8","prompt":"Which name matches the alkene C₄H₈?","choices":["Butene","Butane","Propene"],"answer":0,"hint":"The stem gives the number of carbons and the ending tells you the family.","explain":"But- means 4 carbons and -ene means a C=C, so C₄H₈ is butene. Butane is C₄H₁₀ and propene is C₃H₆."}]},"practice":[{"type":"mc","id":"p1","prompt":"What makes a hydrocarbon an alkene?","choices":["It has one carbon–carbon double bond","It has only single bonds","It contains oxygen as well as carbon"],"answer":0,"hint":"Look at the -ene ending and the bond between two carbons in ethene.","explain":"An alkene has a C=C double bond. Hydrocarbons with only single bonds are alkanes, and a hydrocarbon contains no oxygen."},{"type":"numeric","id":"p2","prompt":"An alkene has {n} carbon atoms. How many hydrogen atoms does it have?","answer":"2*n","hint":"Use CₙH₂ₙ: the number of hydrogens is twice the number of carbons.","explain":"2 × {n} = {=2*n}, so the alkene is C{n}H{=2*n}.","params":{"n":[2,8]}},{"type":"numeric","id":"p3","prompt":"An alkene has {n} carbon atoms. Using C = 12 and H = 1, what is its relative formula mass?","answer":"14*n","hint":"Work out the formula with CₙH₂ₙ first, then add 12 for each C and 1 for each H.","explain":"The alkene is C{n}H{=2*n}: {n} × 12 + {=2*n} × 1 = {=14*n}. Each CH₂ adds 14.","params":{"n":[2,7]}},{"type":"mc","id":"p4","prompt":"Which formula belongs to an alkene?","choices":["C₄H₈","C₄H₁₀","C₄H₉"],"answer":0,"hint":"Check whether the number of hydrogens is exactly twice the number of carbons.","explain":"C₄H₈ fits CₙH₂ₙ, so it is butene. C₄H₁₀ fits CₙH₂ₙ₊₂, butane, and no stable hydrocarbon is C₄H₉."},{"type":"mc","id":"p5","prompt":"Why is ethene described as unsaturated?","choices":["Its C=C bond can open and add more atoms","It does not dissolve in water","It has fewer carbon atoms than ethane"],"answer":0,"hint":"Saturated means full. What can happen to the double bond?","explain":"Unsaturated means more atoms can still be added. The C=C can open, for example adding bromine to make C₂H₄Br₂. Ethene and ethane both have 2 carbons."}],"explain":{"kid":["Alkenes are a family of hydrocarbons. That means they are made of only carbon and hydrogen. Every alkene has two carbons joined by a double bond, written C=C.","A carbon atom always makes four bonds. The double bond uses up two of them. So the two carbons in the C=C each have room for one hydrogen less than in an alkane.","The smallest alkene is ethene, C₂H₄. Next come propene, C₃H₆, and butene, C₄H₈. Look at the numbers. There are always twice as many hydrogens as carbons.","Alkenes are called unsaturated. The double bond can open up and grab more atoms. You can test for this with orange bromine water. Shake it with an alkene and the colour vanishes. With an alkane it stays orange."],"adult":["An alkene is a hydrocarbon containing one carbon–carbon double bond. The names end in -ene: ethene, propene, butene, pentene. Each name uses the same stem as the alkane with the same number of carbons.","Carbon forms four bonds, and the C=C counts as two of them. Each carbon in the double bond therefore holds one hydrogen fewer than in the matching alkane. That makes two fewer in total, so the general formula is CₙH₂ₙ rather than CₙH₂ₙ₊₂. Propene is CH₂=CH–CH₃.","Alkanes are saturated: every carbon already has four single bonds, so no more atoms can be added. Alkenes are unsaturated, because the C=C can open and bond to new atoms. With bromine, ethene forms C₂H₄Br₂. That addition removes the orange colour of bromine water, which is the standard test for a C=C.","Common mistakes: drawing three hydrogens on a C=C carbon, so each carbon has five bonds; removing only one hydrogen for the double bond; and reversing the bromine water test. Be careful too with ring compounds. A ring of carbons can also fit CₙH₂ₙ, so the formula alone suggests a chain alkene, but the drawing settles it."]},"familyTip":"Use dried pasta for bonds and coins for atoms. Build ethane with single pasta bonds, then rebuild it as ethene with two pieces of pasta between the carbons. Count how many coin hydrogens you had to take away, and check every carbon still has four pieces of pasta."},"mt_ylruY6VhOf":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Oxygen melts at −218 °C and boils at −183 °C. What state is oxygen in at {t} °C?","choices":["Gas","Liquid","Solid"],"answer":0,"hint":"Compare {t} °C with its boiling point.","explain":"{t} °C is far above oxygen's boiling point of −183 °C, so it is a gas.","params":{"t":[0,30]}},{"type":"mc","id":"m2","prompt":"A metal melts at {m} °C. What state is it in at {t} °C?","choices":["Solid","Liquid","Gas"],"answer":0,"hint":"Is it hot enough to melt?","explain":"{t} °C is below its melting point of {m} °C, so it is still solid.","params":{"m":[300,320],"t":[20,40]}},{"type":"mc","id":"m3","prompt":"Which state keeps its own shape?","choices":["Solid","Liquid","Gas"],"answer":0,"hint":"Which particles are fixed in place?","explain":"Solid particles are held in a fixed pattern, so a solid keeps its shape."},{"type":"mc","id":"m4","prompt":"A smell spreads across a room. Why?","choices":["Gas particles move around and spread out","Smells are not made of particles","Only warm air can carry smells"],"answer":0,"hint":"Gas particles move in all directions.","explain":"The smell's gas particles move and mix with the air particles until they spread out."},{"type":"mc","id":"m5","prompt":"What is between the particles in a gas?","choices":["Empty space","Air","Water"],"answer":0,"hint":"Air is itself made of particles.","explain":"Nothing: there is empty space. Air can't be between them, because air is made of particles too."},{"type":"mc","id":"m6","prompt":"Ice and liquid water are made of the same particles. What is different?","choices":["How the particles are arranged and move","The size of the particles","What the particles are made of"],"answer":0,"hint":"Same particles, different state.","explain":"Only the arrangement and movement change; the particles are the same."},{"type":"mc","id":"m7","prompt":"When you heat a gas in a sealed box, its particles…","choices":["move faster","get bigger","turn into a liquid"],"answer":0,"hint":"Heating gives particles energy.","explain":"More energy means faster particles. They don't grow."}]},"practice":[{"type":"mc","id":"p1","prompt":"In which state are the particles far apart and moving fast in all directions?","choices":["Gas","Liquid","Solid"],"answer":0,"hint":"Which state spreads out to fill a room?","explain":"In a gas the particles are far apart and move quickly."},{"type":"mc","id":"p2","prompt":"A substance melts at {m} °C and boils at {b} °C. What state is it in at {t} °C?","choices":["Liquid, because {t} °C is between its melting and boiling points","Solid, because {t} °C is below its boiling point","Gas, because {t} °C is above its melting point"],"answer":0,"hint":"Is {t} °C above the melting point? Is it below the boiling point?","explain":"{t} °C is above {m} °C (so it has melted) and below {b} °C (so it hasn't boiled). It is a liquid.","params":{"m":[10,30],"b":[80,100],"t":[40,60]}},{"type":"mc","id":"p3","prompt":"Why can a gas be squashed but a solid can't?","choices":["Gas particles have big spaces between them","Gas particles are smaller","Solid particles are glued together"],"answer":0,"hint":"Think about spacing.","explain":"There is space between gas particles to push them into. Solid particles are already touching."},{"type":"mc","id":"p4","prompt":"When ice melts, what happens to its particles?","choices":["They gain energy and start to slide past each other","They melt into smaller particles","They get bigger"],"answer":0,"hint":"The particles themselves don't change.","explain":"The particles gain energy and break out of their fixed pattern. They are still the same particles."},{"type":"numeric","id":"p5","prompt":"A sealed syringe holds {v} cm³ of air. You push the plunger until the air takes up half the space. What is the new volume in cm³?","answer":"v/2","hint":"Halve {v}.","explain":"Half of {v} is {=v/2} cm³. The same particles are just pushed closer together.","params":{"v":[10,50]},"where":"v%2==0"}],"explain":{"kid":["All matter is made of particles that are far too small to see. In a solid, the particles are packed tightly in a fixed pattern and can only vibrate. In a liquid, they are close together but can slide past each other. In a gas, they are far apart and move fast in all directions.","This explains what we see. A solid keeps its shape. A liquid takes the shape of its container. A gas spreads out to fill any space."],"adult":["The particle model explains properties we can see. Gases can be squashed because there is empty space between the particles. Solids and liquids hardly squash at all, because their particles are already touching.","Heating gives particles more energy, so they vibrate or move faster. That's why heating can melt a solid or boil a liquid. The particles themselves do not get bigger or melt."]},"familyTip":"Fill a syringe (with no needle) with air, block the end with your finger and push. Then try it with water."},"mt_b6kZgqolEd":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A stone has a mass of {=d*v} g and a volume of {v} cm³. Find its density in g/cm³.","answer":"d","hint":"Mass ÷ volume.","explain":"{=d*v} ÷ {v} = {d} g/cm³.","params":{"d":[2,8],"v":[3,12]}},{"type":"numeric","id":"m2","prompt":"A metal has a density of {d} g/cm³. What is the mass of {v} cm³ of it, in g?","answer":"d*v","hint":"Density × volume.","explain":"{d} × {v} = {=d*v} g.","params":{"d":[2,11],"v":[2,10]}},{"type":"mc","id":"m3","prompt":"Which is best explained by particles being far apart?","choices":["Gases are easy to squash","Solids keep their shape","Liquids are hard to squash"],"answer":0,"hint":"Squashing needs space.","explain":"Gases squash because there is space between their particles."},{"type":"mc","id":"m4","prompt":"100 g of ice melts. What is the mass of the water?","choices":["100 g","Less than 100 g","More than 100 g"],"answer":0,"hint":"Are any particles lost?","explain":"Still 100 g. The same particles are just arranged differently."},{"type":"mc","id":"m5","prompt":"Which is a limit of the simple particle model?","choices":["It shows particles as hard balls, which they are not","It can't explain melting","It says gases have no particles"],"answer":0,"hint":"What do the diagrams leave out?","explain":"Real particles aren't hard spheres, and the diagrams don't show the forces between them."},{"type":"mc","id":"m6","prompt":"The gas in a balloon is cooled. Its particles…","choices":["slow down, and the balloon shrinks","shrink in size","stop moving completely"],"answer":0,"hint":"Less energy means less movement.","explain":"The particles slow down and hit the walls less, so the balloon shrinks. The particles stay the same size."},{"type":"mc","id":"m7","prompt":"Usually, which state of a substance has the highest density?","choices":["Solid","Liquid","Gas"],"answer":0,"hint":"Where are particles packed closest?","explain":"Usually the solid. Water is a famous exception: ice floats because it is less dense than water."}]},"practice":[{"type":"numeric","id":"p1","prompt":"A block has a mass of 54 g and a volume of 20 cm³. What is its density in g/cm³?","answer":2.7,"hint":"Mass ÷ volume.","explain":"54 ÷ 20 = 2.7 g/cm³."},{"type":"numeric","id":"p2","prompt":"An object has a mass of {=d*v} g and a volume of {v} cm³. What is its density in g/cm³?","answer":"d","hint":"Mass ÷ volume.","explain":"{=d*v} ÷ {v} = {d} g/cm³.","params":{"d":[2,9],"v":[2,15]}},{"type":"mc","id":"p3","prompt":"Why is steam much less dense than liquid water?","choices":["The same particles are much more spread out","Steam particles are lighter","Steam has no mass"],"answer":0,"hint":"Same particles, different spacing.","explain":"The particles are identical, but in steam they are far apart, so less mass fits in each cm³."},{"type":"numeric","id":"p4","prompt":"A liquid has a density of {d} g/cm³. What is the mass of {v} cm³ of it, in g?","answer":"d*v","hint":"Mass = density × volume.","explain":"{d} × {v} = {=d*v} g.","params":{"d":[1,3],"v":[10,50]}},{"type":"mc","id":"p5","prompt":"When water boils, what is overcome?","choices":["The forces between water particles","The bonds inside each water particle","Nothing: the particles just get bigger"],"answer":0,"hint":"Boiling doesn't make a new substance.","explain":"Boiling overcomes the forces between particles. Each water particle stays whole."}],"explain":{"kid":["The particle model explains things using particles. In a solid, particles are close and fixed. In a liquid they are close but move around. In a gas they are spread out.","Density is how much mass is packed into a space. Most solids are dense, because their particles are packed closely. Gases have a low density, because their particles are far apart."],"adult":["Density = mass ÷ volume, often in g/cm³. A 20 cm³ block with a mass of 54 g has a density of 54 ÷ 20 = 2.7 g/cm³. A change of state changes the spacing, so it changes the density. The mass stays the same.","Every model has limits. Real particles are not hard little balls. Simple diagrams also leave out the forces between them. Even so, the model predicts a lot."]},"familyTip":"Weigh a full glass of water, then work out its density using the volume printed on a measuring jug."},"mt_Z_Wu_77ybI":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"How many atoms in total are in {n} molecules of carbon dioxide, CO₂?","answer":"3*n","hint":"Each CO₂ has 1 + 2 atoms.","explain":"3 atoms each, so {n} × 3 = {=3*n}.","params":{"n":[2,12]}},{"type":"numeric","id":"m2","prompt":"How many oxygen atoms are in {n} molecules of oxygen, O₂?","answer":"2*n","hint":"Each O₂ has 2 atoms.","explain":"{n} × 2 = {=2*n}.","params":{"n":[2,15]}},{"type":"mc","id":"m3","prompt":"Which is a compound?","choices":["CO₂","O₂","Fe"],"answer":0,"hint":"More than one element, joined.","explain":"CO₂ has carbon and oxygen joined together."},{"type":"mc","id":"m4","prompt":"What is the symbol for iron?","choices":["Fe","I","Ir"],"answer":0,"hint":"It comes from the Latin word ferrum.","explain":"Fe. (I is iodine and Ir is iridium.)"},{"type":"mc","id":"m5","prompt":"Where are the protons and neutrons in an atom?","choices":["In the nucleus","In the shells","Spread evenly through the atom"],"answer":0,"hint":"The tiny centre.","explain":"Protons and neutrons are in the nucleus; electrons are in shells."},{"type":"mc","id":"m6","prompt":"Which statement about water, H₂O, is true?","choices":["Each molecule has 2 hydrogen atoms and 1 oxygen atom","Each molecule has 2 oxygen atoms","It is a mixture of hydrogen and oxygen"],"answer":0,"hint":"The small 2 belongs to H.","explain":"H₂O: 2 hydrogen and 1 oxygen, chemically joined, so it's a compound."},{"type":"mc","id":"m7","prompt":"What is the difference between a carbon atom and the element carbon?","choices":["An atom is one particle; the element is a substance made only of carbon atoms","There is no difference at all","The element contains other atoms too"],"answer":0,"hint":"One particle, or a lot of them?","explain":"An element is made of many atoms, all of the same type."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which of these is an element?","choices":["Oxygen, O₂","Water, H₂O","Carbon dioxide, CO₂"],"answer":0,"hint":"Look for only one kind of atom.","explain":"O₂ has only oxygen atoms, so it's an element, even though the atoms are joined in pairs."},{"type":"numeric","id":"p2","prompt":"How many atoms are in {n} molecules of water, H₂O?","answer":"3*n","hint":"Each H₂O has 2 + 1 atoms.","explain":"Each H₂O has 3 atoms, so {n} × 3 = {=3*n}.","params":{"n":[2,12]}},{"type":"mc","id":"p3","prompt":"What decides which element an atom is?","choices":["The number of protons","The number of neutrons","Its size"],"answer":0,"hint":"It's the atomic number.","explain":"The number of protons is the atomic number, and it decides the element."},{"type":"numeric","id":"p4","prompt":"How many hydrogen atoms are in {n} molecules of methane, CH₄?","answer":"4*n","hint":"Each CH₄ has 4 hydrogen atoms.","explain":"{n} × 4 = {=4*n}.","params":{"n":[2,12]}},{"type":"mc","id":"p5","prompt":"Sodium is a reactive metal and chlorine is a toxic gas. What is sodium chloride like?","choices":["A safe white solid: table salt","A reactive, toxic metal","A mixture you can separate with a magnet"],"answer":0,"hint":"Compounds are new substances.","explain":"Sodium chloride is table salt. Its properties are completely different from its elements."}],"explain":{"kid":["Atoms are the smallest bits of an element. There are about 118 elements. Oxygen, iron and carbon are three of them. Each element has its own kind of atom and a short symbol: O for oxygen, Fe for iron.","A compound forms when atoms of different elements join. Water, H₂O, is a compound. Each water particle has two hydrogen atoms joined to one oxygen atom."],"adult":["An atom has a tiny central nucleus, made of protons and neutrons. Electrons are arranged in shells around it. The number of protons decides which element the atom is.","Compounds can behave very differently from their elements. Sodium is a reactive metal and chlorine is a toxic gas. Together they make sodium chloride, which is table salt. A formula like CO₂ gives the ratio of atoms: one carbon to two oxygen."]},"familyTip":"Read the ingredients on a food or cleaning label. Which names are elements and which are compounds?"},"mt_MBTVB-E-S7":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A pure substance melts at {m} °C. An impure sample of it will probably melt…","choices":["below {m} °C, over a range","at exactly {m} °C","above {=m+20} °C"],"answer":0,"hint":"Impurities lower and spread the melting point.","explain":"Impurities lower the melting point and spread it over a range, so below {m} °C.","params":{"m":[50,120]}},{"type":"numeric","id":"m2","prompt":"A fertiliser is {p}% nitrogen. How many kg of nitrogen are in {=k*10} kg?","answer":"p*k/10","hint":"Find {p}% of {=k*10}.","explain":"{p}% of {=k*10} kg = {=p*k/10} kg.","params":{"p":[10,30],"k":[1,9]}},{"type":"mc","id":"m3","prompt":"Which is a mixture?","choices":["Air","Oxygen","Carbon dioxide"],"answer":0,"hint":"Which has several substances not joined?","explain":"Air is a mixture of nitrogen, oxygen, argon, carbon dioxide and more."},{"type":"mc","id":"m4","prompt":"A label says 'pure apple juice'. Is it pure in the science sense?","choices":["No: it's a mixture of water, sugars and other substances","Yes, because nothing was added","Yes, because it is all one colour"],"answer":0,"hint":"Science 'pure' means one substance.","explain":"Even with nothing added, juice contains many substances."},{"type":"mc","id":"m5","prompt":"Which is a formulation?","choices":["Paint","Gold","Sea water"],"answer":0,"hint":"A mixture designed for a purpose, with exact amounts.","explain":"Paint is made to a recipe with exact amounts. Sea water is a mixture, but not designed."},{"type":"mc","id":"m6","prompt":"How could you test whether a white solid is pure?","choices":["Measure its melting point","Look at its colour","Weigh it"],"answer":0,"hint":"Pure substances melt at one temperature.","explain":"A sharp melting point at the expected value shows it is pure."},{"type":"mc","id":"m7","prompt":"Salt dissolved in water is…","choices":["a mixture","a compound","an element"],"answer":0,"hint":"Are the salt and water chemically joined?","explain":"The salt and water are not joined, so it is a mixture; you can get the salt back by evaporating."}]},"practice":[{"type":"mc","id":"p1","prompt":"In science, which is pure?","choices":["Distilled water","Fresh orange juice","Sea water"],"answer":0,"hint":"One substance only.","explain":"Distilled water contains only water. The others are mixtures."},{"type":"mc","id":"p2","prompt":"A sample melts over a range, from {a} °C to {=a+r} °C. What does this suggest?","choices":["It is a mixture (impure)","It is a pure substance","It is an element"],"answer":0,"hint":"Pure substances melt at one temperature.","explain":"Melting over a {r} °C range suggests impurities.","params":{"a":[40,80],"r":[3,9]}},{"type":"numeric","id":"p3","prompt":"A formulation is {p}% active ingredient. How many grams of active ingredient are in {=k*100} g?","answer":"p*k","hint":"Find {p}% of {=k*100}.","explain":"{p}% of {=k*100} g = {=p*k} g.","params":{"p":[5,40],"k":[1,9]}},{"type":"mc","id":"p4","prompt":"What is the difference between a mixture and a compound?","choices":["In a compound, the elements are chemically joined in a fixed ratio","A mixture is always a liquid","A compound can be separated by filtering"],"answer":0,"hint":"Joined, or just mixed?","explain":"Compound: elements joined in a fixed ratio. Mixture: substances not joined, in any amounts."},{"type":"mc","id":"p5","prompt":"Pure water boils at 100 °C at normal pressure. A water sample boils at {t} °C. What does that suggest?","choices":["It is not pure","It is pure","It has turned into a different compound"],"answer":0,"hint":"Pure water boils at exactly one temperature.","explain":"Boiling at {t} °C suggests something is dissolved in the water.","params":{"t":[101,106]}}],"explain":{"kid":["In science, 'pure' means one substance only, with nothing else mixed in. Pure water is only water particles. 'Pure' orange juice is a mixture of water, sugars and more.","A mixture has two or more substances that are not joined together. Air, sea water and salad are mixtures. You can often separate a mixture, for example by filtering or evaporating."],"adult":["You can test purity by melting or boiling. A pure substance changes state at one fixed temperature. Pure water boils at 100 °C at normal air pressure. Impurities lower the melting point and spread it over a range.","A formulation is a mixture designed for a job, with exact amounts of each part. Paints, medicines and fertilisers are formulations. Compounds are different from mixtures: their elements are chemically joined, in a fixed ratio."]},"familyTip":"Look at three drinks or foods at home. Which are pure in the science sense? (Hint: almost none.)"},"mt_wfEfQuHOG-":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"A neutral atom has {z} electrons. What is its atomic number?","answer":"z","hint":"Electrons = protons in a neutral atom.","explain":"It has {z} protons, so its atomic number is {z}.","params":{"z":[1,36]}},{"type":"numeric","id":"m2","prompt":"An element has atomic number {z}. How many electrons does a neutral atom of it have?","answer":"z","hint":"Same as the protons.","explain":"{z} protons, so {z} electrons.","params":{"z":[1,36]}},{"type":"mc","id":"m3","prompt":"Elements in the same group…","choices":["have similar chemical properties","have the same mass","are all gases"],"answer":0,"hint":"That's why groups are useful.","explain":"Elements in a group react in similar ways."},{"type":"mc","id":"m4","prompt":"What did Mendeleev do that made his table so convincing?","choices":["He left gaps and predicted elements that were found later","He discovered every element","He put the elements in alphabetical order"],"answer":0,"hint":"Think about predictions.","explain":"His gaps predicted elements such as gallium and germanium, which were later found."},{"type":"mc","id":"m5","prompt":"Which group contains the noble gases, which barely react?","choices":["Group 0 (also called Group 18)","Group 1","Group 7"],"answer":0,"hint":"The far right column.","explain":"The noble gases are in Group 0, also numbered Group 18."},{"type":"mc","id":"m6","prompt":"What is the atomic number of an element?","choices":["The number of protons in its atoms","The number of neutrons","Its position in the alphabet"],"answer":0,"hint":"It decides the element.","explain":"It is the number of protons."},{"type":"mc","id":"m7","prompt":"Which of these is a non-metal?","choices":["Sulfur","Iron","Sodium"],"answer":0,"hint":"Non-metals are on the right.","explain":"Sulfur is a non-metal; iron and sodium are metals."}]},"practice":[{"type":"mc","id":"p1","prompt":"What are the columns of the periodic table called?","choices":["Groups","Periods","Shells"],"answer":0,"hint":"Rows are periods.","explain":"Columns are groups; rows are periods."},{"type":"numeric","id":"p2","prompt":"An element has atomic number {z}. How many protons are in each of its atoms?","answer":"z","hint":"Atomic number = number of protons.","explain":"The atomic number is the number of protons, so {z}.","params":{"z":[1,30]}},{"type":"mc","id":"p3","prompt":"Where are the metals in the periodic table?","choices":["On the left and in the middle","Only in the top row","On the far right"],"answer":0,"hint":"Non-metals are on the right.","explain":"Most elements are metals, filling the left and middle."},{"type":"numeric","id":"p4","prompt":"A neutral atom has {z} protons. How many electrons does it have?","answer":"z","hint":"Neutral means the charges balance.","explain":"A neutral atom has as many electrons as protons: {z}.","params":{"z":[1,30]}},{"type":"mc","id":"p5","prompt":"Lithium, sodium and potassium are in Group 1. Which is the most reactive?","choices":["Potassium","Lithium","They are all the same"],"answer":0,"hint":"Reactivity increases down Group 1.","explain":"Potassium is lowest of the three, so it is most reactive."}],"explain":{"kid":["The periodic table lists every element. Each box shows a symbol and a number, such as 6 for carbon. That number is the atomic number: how many protons each atom has.","Columns are called groups. Elements in the same group behave in similar ways. Rows are called periods. Metals are on the left and in the middle, and non-metals are on the right."],"adult":["In 1869 Dmitri Mendeleev put the known elements in order. He left gaps for elements no one had found yet and predicted their properties. When gallium and germanium were discovered, his predictions matched.","Patterns run down each group. In Group 1, the alkali metals, reactivity increases as you go down: lithium fizzes in water, while potassium bursts into a lilac flame. Group 0 (also called Group 18) holds the noble gases, which barely react at all."]},"familyTip":"Find a periodic table online and look up five elements you use at home."},"mt_t20A6RuTJn":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"How many atoms in total are in {n}CH₄?","answer":"5*n","hint":"Each CH₄ has 1 + 4 atoms.","explain":"Each CH₄ has 5 atoms, so {n} × 5 = {=5*n}.","params":{"n":[2,9]}},{"type":"numeric","id":"m2","prompt":"How many oxygen atoms are in {n}Ca(OH)₂?","answer":"2*n","hint":"Each Ca(OH)₂ has 2 oxygen atoms.","explain":"{n} × 2 = {=2*n} oxygen atoms.","params":{"n":[2,6]}},{"type":"numeric","id":"m3","prompt":"How many hydrogen atoms are in 2NH₃?","answer":6,"hint":"2 molecules × 3 hydrogen atoms.","explain":"2 × 3 = 6."},{"type":"numeric","id":"m4","prompt":"How many atoms in total are in Mg(NO₃)₂?","answer":9,"hint":"The bracket doubles N and O₃.","explain":"1 Mg + 2 N + 6 O = 9 atoms."},{"type":"mc","id":"m5","prompt":"How many oxygen atoms are in Al₂(SO₄)₃?","choices":["12","4","7"],"answer":0,"hint":"The bracket is multiplied by 3.","explain":"4 oxygen atoms × 3 = 12. Adding 4 + 3 = 7 is a common slip."},{"type":"mc","id":"m6","prompt":"How many atoms of each element are in H₂SO₄?","choices":["2 H, 1 S, 4 O","2 H, 2 S, 4 O","1 H, 1 S, 1 O"],"answer":0,"hint":"Each small number belongs to the symbol just before it.","explain":"H₂ gives 2 H, S has no number so 1, O₄ gives 4."},{"type":"numeric","id":"m7","prompt":"The right-hand side of an equation has {n}H₂O. How many hydrogen atoms must the left-hand side have?","answer":"2*n","hint":"Atoms are not made or destroyed.","explain":"{n} × 2 = {=2*n}, so the left needs {=2*n} hydrogen atoms too.","params":{"n":[2,8]}}]},"practice":[{"type":"numeric","id":"p1","prompt":"How many atoms in total are in one H₂O molecule?","answer":3,"hint":"2 hydrogen + 1 oxygen.","explain":"2 + 1 = 3 atoms."},{"type":"numeric","id":"p2","prompt":"How many hydrogen atoms are in {n}H₂O?","answer":"2*n","hint":"{n} molecules, each with 2 hydrogen atoms.","explain":"{n} × 2 = {=2*n} hydrogen atoms.","params":{"n":[2,9]}},{"type":"numeric","id":"p3","prompt":"How many oxygen atoms are in Ca(OH)₂?","answer":2,"hint":"The bracket is doubled.","explain":"(OH) × 2 gives 2 oxygen atoms."},{"type":"numeric","id":"p4","prompt":"How many oxygen atoms are in {n}CO₂?","answer":"2*n","hint":"Each CO₂ has 2 oxygen atoms.","explain":"{n} × 2 = {=2*n} oxygen atoms.","params":{"n":[2,9]}},{"type":"mc","id":"p5","prompt":"In 3H₂O, what does the 3 mean?","choices":["3 water molecules","3 hydrogen atoms","3 oxygen atoms"],"answer":0,"hint":"A big number in front counts molecules.","explain":"3H₂O is three whole water molecules."}],"explain":{"kid":["In H₂O, the small 2 belongs to the H. So there are 2 hydrogen atoms and 1 oxygen atom: 3 atoms in all.","A big number in front counts molecules. 3H₂O means 3 water molecules. That is 3 × 2 = 6 hydrogen atoms and 3 oxygen atoms."],"adult":["Brackets multiply everything inside them. In Ca(OH)₂ there is 1 calcium, 2 oxygen and 2 hydrogen atoms: 5 atoms in total.","Use both rules together when needed. 2Ca(OH)₂ has 2 calcium, 4 oxygen and 4 hydrogen atoms. In an equation, count each element on each side. A balanced equation has the same totals on both sides."]},"familyTip":"Write formulae on cards (H₂O, CO₂, 2NH₃) and race each other to count the atoms."},"mt_ehC1wsdmUz":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"In an open beaker, {m} g of chemicals fizz and give off a gas. Afterwards the beaker's contents have a mass of {=m-g} g. What mass of gas escaped, in g?","answer":"g","hint":"Find the difference.","explain":"{m} − {=m-g} = {g} g of gas escaped.","params":{"m":[100,200],"g":[2,15]}},{"type":"numeric","id":"m2","prompt":"{=7*k} g of iron reacts with {=4*k} g of sulfur to make iron sulfide. Nothing escapes. What mass of iron sulfide forms, in g?","answer":"11*k","hint":"Add the masses.","explain":"{=7*k} + {=4*k} = {=11*k} g.","params":{"k":[1,9]}},{"type":"mc","id":"m3","prompt":"An iron nail rusts and gets heavier. Where does the extra mass come from?","choices":["Oxygen (and water) from the air","Nowhere: rust is made from nothing","The nail grows"],"answer":0,"hint":"Rust forms when iron reacts with something.","explain":"Iron reacts with oxygen and water from the air, so their mass joins the nail."},{"type":"mc","id":"m4","prompt":"In a sealed container, which change does NOT conserve mass?","choices":["None: mass is always conserved","Melting","Burning"],"answer":0,"hint":"Think about every kind of change.","explain":"Mass is conserved in every change if nothing gets in or out."},{"type":"mc","id":"m5","prompt":"Sugar dissolves in tea and can't be seen. Where is it?","choices":["Its particles are spread out between the water particles","It has been destroyed","It has turned into water"],"answer":0,"hint":"Can you still taste it?","explain":"The sugar particles are still there, spread through the water."},{"type":"numeric","id":"m6","prompt":"40 g of vinegar and 5 g of baking soda react in a sealed bottle. What is the total mass afterwards, in g?","answer":45,"hint":"Sealed: nothing escapes.","explain":"40 + 5 = 45 g."},{"type":"mc","id":"m7","prompt":"Why do scientists seal the container when testing conservation of mass?","choices":["So no gas can get in or out","To keep it warm","To speed up the reaction"],"answer":0,"hint":"Gases are easy to lose.","explain":"Sealing stops gases escaping or entering, so the total mass can be compared fairly."}]},"practice":[{"type":"numeric","id":"p1","prompt":"10 g of sugar dissolves in 200 g of water. What is the mass of the solution, in g?","answer":210,"hint":"Add the masses.","explain":"10 + 200 = 210 g."},{"type":"numeric","id":"p2","prompt":"{s} g of salt dissolves in {w} g of water. What is the mass of the salt water, in g?","answer":"s+w","hint":"Nothing is lost when it dissolves.","explain":"{s} + {w} = {=s+w} g. The salt is still there.","params":{"s":[5,30],"w":[100,250]}},{"type":"mc","id":"p3","prompt":"An ice cube with a mass of 25 g melts. What is the mass of the water?","choices":["25 g","Less than 25 g","More than 25 g"],"answer":0,"hint":"No particles are lost.","explain":"Still 25 g. Melting doesn't change the mass."},{"type":"numeric","id":"p4","prompt":"In a sealed flask, chemicals with a total mass of {m} g react and make a gas. What is the total mass afterwards, in g?","answer":"m","hint":"Can the gas escape?","explain":"The flask is sealed, so nothing escapes. The mass stays {m} g.","params":{"m":[100,300]}},{"type":"mc","id":"p5","prompt":"Wood burns in an open fire. The ash is lighter than the wood. Why?","choices":["Gases made in burning escape into the air","Some mass is destroyed","The fire uses some mass up as heat"],"answer":0,"hint":"Where do the products go?","explain":"Carbon dioxide and water vapour escape. Their mass plus the ash equals the wood plus the oxygen used."}],"explain":{"kid":["If you dissolve 10 g of sugar in 200 g of water, the solution has a mass of 210 g. The sugar seems to vanish, but its particles are still there, spread out in the water.","This is true for every change: melting, freezing, dissolving and even burning. Nothing is made from nothing, and nothing just disappears. We call this conservation of mass."],"adult":["Sometimes mass seems to change. When wood burns in the open, the ash is lighter. That's because gases, carbon dioxide and water vapour, escape into the air. A rusting nail gets heavier, because it gains oxygen from the air.","If the change happens in a sealed container, the total mass stays exactly the same. Scientists use this to check results, and to work out the mass of a gas that escaped."]},"familyTip":"Weigh a glass of water and a spoonful of sugar, stir the sugar in, then weigh again."},"mt_tFOhzG3wLi":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"{=4*k} g of hydrogen reacts with {=32*k} g of oxygen to make water. What mass of water forms, in g?","answer":"36*k","hint":"Add the masses.","explain":"{=4*k} + {=32*k} = {=36*k} g.","params":{"k":[1,6]}},{"type":"numeric","id":"m2","prompt":"The products of a reaction contain {n} carbon atoms. How many carbon atoms were in the reactants?","answer":"n","hint":"Atoms are not created or destroyed.","explain":"The same {n} carbon atoms.","params":{"n":[2,20]}},{"type":"mc","id":"m3","prompt":"Why is mass conserved in a reaction?","choices":["The same atoms are there before and after","The products are always heavier","Energy turns into mass"],"answer":0,"hint":"Count the atoms.","explain":"No atoms are gained or lost, so the mass stays the same."},{"type":"mc","id":"m4","prompt":"In 2H₂ + O₂ → 2H₂O, how many hydrogen atoms are on the right?","choices":["4","2","6"],"answer":0,"hint":"2 molecules × 2 atoms.","explain":"2H₂O has 2 × 2 = 4 hydrogen atoms."},{"type":"mc","id":"m5","prompt":"Iron and sulfur are heated and make iron sulfide. Which is true?","choices":["It is a new substance with different properties","It is a mixture you can separate with a magnet","The iron atoms turn into sulfur atoms"],"answer":0,"hint":"A reaction makes a new substance.","explain":"Iron sulfide is a compound. It isn't magnetic like iron, and atoms never change element."},{"type":"mc","id":"m6","prompt":"Which of these is a chemical reaction rather than a change of state?","choices":["Burning magnesium","Melting ice","Boiling water"],"answer":0,"hint":"Which makes a new substance?","explain":"Burning magnesium makes magnesium oxide, a new substance."},{"type":"numeric","id":"m7","prompt":"C + O₂ → CO₂. 12 g of carbon reacts completely with 32 g of oxygen. What mass of carbon dioxide forms, in g?","answer":44,"hint":"Add the masses.","explain":"12 + 32 = 44 g."}]},"practice":[{"type":"mc","id":"p1","prompt":"In a chemical reaction, what happens to the atoms?","choices":["They are rearranged into new substances","Some are destroyed","New atoms are created"],"answer":0,"hint":"Atoms swap partners.","explain":"The same atoms join up in new ways."},{"type":"numeric","id":"p2","prompt":"{=3*k} g of magnesium reacts completely with {=2*k} g of oxygen to make magnesium oxide. What mass of magnesium oxide forms, in g?","answer":"5*k","hint":"All the atoms end up in the product.","explain":"{=3*k} + {=2*k} = {=5*k} g.","params":{"k":[1,12]}},{"type":"mc","id":"p3","prompt":"In C + O₂ → CO₂, how many oxygen atoms are on each side?","choices":["2 on each side","2 on the left and 1 on the right","1 on each side"],"answer":0,"hint":"Count the small numbers.","explain":"O₂ has 2, and CO₂ has 2."},{"type":"numeric","id":"p4","prompt":"A reaction makes {n}H₂O. How many oxygen atoms must the reactants contain?","answer":"n","hint":"Each H₂O has 1 oxygen atom.","explain":"{n} × 1 = {n} oxygen atoms. Atoms are not created or destroyed.","params":{"n":[2,9]}},{"type":"mc","id":"p5","prompt":"What are the starting substances in a reaction called?","choices":["Reactants","Products","Catalysts"],"answer":0,"hint":"They react.","explain":"Reactants go in; products come out."}],"explain":{"kid":["In a chemical reaction, the starting substances are called reactants. The new substances are called products. The atoms swap partners, but they are all still there.","When carbon burns in oxygen, one carbon atom joins two oxygen atoms. Together they make carbon dioxide, CO₂. There is 1 carbon atom before and after, and 2 oxygen atoms before and after."],"adult":["Because every atom is still there, the total mass of the products equals the total mass of the reactants. This is the particle-level reason for conservation of mass.","Particle diagrams show this well. Draw 2H₂ + O₂ → 2H₂O. On the left there are 4 hydrogen atoms and 2 oxygen atoms. On the right there are 4 hydrogen atoms and 2 oxygen atoms. Only the partners have changed."]},"familyTip":"Use coloured sweets or building bricks as atoms. Build the reactants, then rebuild them into the products without adding or removing any."},"mt_dzgK92gM32":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"magnesium carbonate → magnesium oxide + carbon dioxide. {=84*k} g of magnesium carbonate makes {=40*k} g of magnesium oxide. What mass of carbon dioxide is made, in g?","answer":"44*k","hint":"Subtract.","explain":"{=84*k} − {=40*k} = {=44*k} g.","params":{"k":[1,6]}},{"type":"numeric","id":"m2","prompt":"sodium + chlorine → sodium chloride. {=23*k} g of sodium reacts with {=35.5*k} g of chlorine. What mass of sodium chloride forms, in g?","answer":"58.5*k","hint":"Add the masses.","explain":"{=23*k} + {=35.5*k} = {=58.5*k} g.","params":{"k":[1,6]}},{"type":"mc","id":"m3","prompt":"Which word equation shows methane burning completely?","choices":["methane + oxygen → carbon dioxide + water","methane → carbon + hydrogen","methane + water → oxygen"],"answer":0,"hint":"Fuel + oxygen → ?","explain":"Complete burning of a hydrocarbon gives carbon dioxide and water."},{"type":"mc","id":"m4","prompt":"Which elements are in copper sulfate?","choices":["Copper, sulfur and oxygen","Copper and sulfur only","Copper and oxygen only"],"answer":0,"hint":"'-ate' means oxygen is included.","explain":"'-ate' tells you there is oxygen too: copper, sulfur and oxygen."},{"type":"mc","id":"m5","prompt":"Complete: hydrochloric acid + sodium hydroxide → sodium chloride + …","choices":["water","hydrogen","carbon dioxide"],"answer":0,"hint":"Acid + alkali → salt + ?","explain":"Acid + alkali → salt + water."},{"type":"mc","id":"m6","prompt":"In 'iron + oxygen → iron oxide', what does the + on the left mean?","choices":["'And': iron and oxygen react together","Add the numbers","The reaction gives off heat"],"answer":0,"hint":"It isn't maths here.","explain":"The + means 'and'."},{"type":"mc","id":"m7","prompt":"What are the reactants in: zinc + copper sulfate → zinc sulfate + copper?","choices":["Zinc and copper sulfate","Zinc sulfate and copper","Only zinc"],"answer":0,"hint":"Reactants are on the left.","explain":"Zinc and copper sulfate are on the left of the arrow."}]},"practice":[{"type":"mc","id":"p1","prompt":"In magnesium + oxygen → magnesium oxide, what is the product?","choices":["Magnesium oxide","Magnesium","Oxygen"],"answer":0,"hint":"Products are on the right.","explain":"Magnesium oxide is on the right of the arrow."},{"type":"numeric","id":"p2","prompt":"iron + sulfur → iron sulfide. {=7*k} g of iron reacts with {=4*k} g of sulfur. What mass of iron sulfide forms, in g?","answer":"11*k","hint":"Mass is conserved.","explain":"{=7*k} + {=4*k} = {=11*k} g.","params":{"k":[1,12]}},{"type":"mc","id":"p3","prompt":"What does the arrow mean in a word equation?","choices":["React to make","Equals","Add together"],"answer":0,"hint":"It shows a change.","explain":"The arrow means the reactants react to make the products."},{"type":"mc","id":"p4","prompt":"Complete: zinc + hydrochloric acid → zinc chloride + …","choices":["hydrogen","water","oxygen"],"answer":0,"hint":"Metal + acid → salt + ?","explain":"Metal + acid → salt + hydrogen."},{"type":"numeric","id":"p5","prompt":"calcium carbonate → calcium oxide + carbon dioxide. Heating {=100*k} g of calcium carbonate makes {=56*k} g of calcium oxide. What mass of carbon dioxide is made, in g?","answer":"44*k","hint":"Total mass stays the same.","explain":"{=100*k} − {=56*k} = {=44*k} g.","params":{"k":[1,5]}}],"explain":{"kid":["A word equation is a short way to describe a reaction. Reactants go on the left and products go on the right. The arrow means 'react to make'.","For example: magnesium + oxygen → magnesium oxide. The + on the left means 'and'. It doesn't mean adding numbers."],"adult":["Names give clues. A compound ending in '-ide' usually has just two elements: sodium chloride is sodium and chlorine. One ending in '-ate' also has oxygen: copper sulfate has copper, sulfur and oxygen.","Some patterns are worth learning. Metal + acid → salt + hydrogen. Acid + alkali → salt + water. When a fuel like methane burns completely: fuel + oxygen → carbon dioxide + water."]},"familyTip":"Write a word equation for something that happens in your kitchen, such as burning gas on a hob."},"mt_BXj4pfdhxO":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"numeric","id":"m1","prompt":"CH₄ + 2O₂ → CO₂ + 2H₂O. How many molecules of O₂ are needed to burn {k} molecules of CH₄?","answer":"2*k","hint":"2 O₂ for each CH₄.","explain":"{k} × 2 = {=2*k} molecules of O₂.","params":{"k":[2,12]}},{"type":"numeric","id":"m2","prompt":"N₂ + 3H₂ → 2NH₃. How many H₂ molecules react with {k} N₂ molecules?","answer":"3*k","hint":"3 H₂ for each N₂.","explain":"{k} × 3 = {=3*k} molecules of H₂.","params":{"k":[2,12]}},{"type":"mc","id":"m3","prompt":"Which equation is balanced?","choices":["CH₄ + 2O₂ → CO₂ + 2H₂O","CH₄ + O₂ → CO₂ + H₂O","CH₄ + O₂ → CO₂ + 2H₂O"],"answer":0,"hint":"Count C, H and O on each side.","explain":"CH₄ + 2O₂ → CO₂ + 2H₂O has 1 C, 4 H and 4 O on each side."},{"type":"mc","id":"m4","prompt":"When balancing, what are you allowed to change?","choices":["The big numbers in front of formulae","The small numbers inside formulae","Both"],"answer":0,"hint":"Small numbers define the substance.","explain":"Only the big numbers (coefficients) may change."},{"type":"numeric","id":"m5","prompt":"Balance: N₂ + □H₂ → 2NH₃. What number goes in the box?","answer":3,"hint":"2NH₃ has 6 hydrogen atoms.","explain":"6 hydrogen atoms need 3H₂, so the number is 3."},{"type":"mc","id":"m6","prompt":"Write 4H₂ + 2O₂ → 4H₂O in its simplest ratio.","choices":["2H₂ + O₂ → 2H₂O","H₂ + O₂ → H₂O","2H₂ + 2O₂ → 2H₂O"],"answer":0,"hint":"Divide every big number by 2.","explain":"Halving gives 2H₂ + O₂ → 2H₂O, which is still balanced."},{"type":"numeric","id":"m7","prompt":"Balance: □Na + Cl₂ → 2NaCl. What number goes in the box?","answer":2,"hint":"2NaCl has 2 sodium atoms.","explain":"2 sodium atoms are needed on the left, so the number is 2."}]},"practice":[{"type":"numeric","id":"p1","prompt":"In □H₂ + O₂ → □H₂O, both boxes hold the same number. What is it?","answer":2,"hint":"Balance the oxygen first.","explain":"2H₂ + O₂ → 2H₂O has 4 H and 2 O on each side, so the number is 2."},{"type":"numeric","id":"p2","prompt":"N₂ + 3H₂ → 2NH₃. How many molecules of NH₃ can {k} molecules of N₂ make, with plenty of H₂?","answer":"2*k","hint":"Each N₂ makes 2NH₃.","explain":"{k} × 2 = {=2*k} molecules of NH₃.","params":{"k":[2,12]}},{"type":"mc","id":"p3","prompt":"Why can't you balance H₂ + O₂ → H₂O by writing H₂O₂?","choices":["H₂O₂ is a different substance (hydrogen peroxide)","H₂O₂ has too many hydrogen atoms","You can: that is correct"],"answer":0,"hint":"What do the small numbers decide?","explain":"Changing a small number changes the substance. H₂O₂ is hydrogen peroxide, not water."},{"type":"numeric","id":"p4","prompt":"Balance: □Mg + O₂ → 2MgO. What number goes in the box?","answer":2,"hint":"How many Mg atoms are on the right?","explain":"2MgO has 2 Mg atoms, so you need 2Mg. Then there are 2 Mg and 2 O on each side."},{"type":"numeric","id":"p5","prompt":"2H₂ + O₂ → 2H₂O. How many molecules of O₂ react with {=2*k} molecules of H₂?","answer":"k","hint":"2 H₂ for every 1 O₂.","explain":"{=2*k} ÷ 2 = {k} molecules of O₂.","params":{"k":[2,12]}}],"explain":{"kid":["H₂ + O₂ → H₂O is not balanced. There are 2 oxygen atoms on the left but only 1 on the right. We can't change H₂O into H₂O₂, because that is a different substance.","Instead, put big numbers in front. 2H₂O gives 2 oxygen atoms, but now 4 hydrogen atoms. So write 2H₂ on the left. Now 2H₂ + O₂ → 2H₂O is balanced: 4 H and 2 O on each side."],"adult":["A good method is to count the atoms of each element on both sides in a table. Balance one element at a time. Leave elements that appear on their own, like O₂, until last. Recount after every change.","Never change the small numbers. That would change the substance itself. Give the final numbers in their simplest ratio: 4H₂ + 2O₂ → 4H₂O should be written as 2H₂ + O₂ → 2H₂O."]},"familyTip":"Use coins or buttons as atoms to model an equation, and check both sides have the same of each."},"mt_v0K6GRi4ZL":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Rusting is an example of…","choices":["oxidation","thermal decomposition","displacement"],"answer":0,"hint":"Iron gains something from the air.","explain":"Iron gains oxygen (with water present): oxidation."},{"type":"mc","id":"m2","prompt":"Which metal can displace copper from copper sulfate solution?","choices":["Zinc","Gold","Silver"],"answer":0,"hint":"It must be more reactive than copper.","explain":"Zinc is more reactive than copper; gold and silver are less reactive."},{"type":"mc","id":"m3","prompt":"What does complete combustion of a fuel like methane produce?","choices":["Carbon dioxide and water","Hydrogen and oxygen","Only smoke"],"answer":0,"hint":"The carbon and hydrogen both join with oxygen.","explain":"Carbon → carbon dioxide; hydrogen → water."},{"type":"numeric","id":"m4","prompt":"A candle burns {a} g of wax using {b} g of oxygen. What total mass of products forms, in grams?","answer":"a+b","hint":"No mass is lost or gained.","explain":"{a} + {b} = {=a+b} g of products.","params":{"a":[2,9],"b":[5,20]}},{"type":"numeric","id":"m5","prompt":"Heating {=a+b} g of copper carbonate leaves {a} g of copper oxide. What mass of gas was given off, in grams?","answer":"b","hint":"The difference is the gas.","explain":"{=a+b} − {a} = {b} g.","params":{"a":[10,30],"b":[4,20]}},{"type":"mc","id":"m6","prompt":"Gold does not react with copper sulfate solution. Why?","choices":["Gold is less reactive than copper","Gold is a gas","Copper sulfate is not a compound"],"answer":0,"hint":"Displacement needs a more reactive metal.","explain":"Only a more reactive metal can push copper out, and gold is less reactive."},{"type":"mc","id":"m7","prompt":"Which word equation shows thermal decomposition?","choices":["calcium carbonate → calcium oxide + carbon dioxide","magnesium + oxygen → magnesium oxide","zinc + copper sulfate → zinc sulfate + copper"],"answer":0,"hint":"One reactant, two products.","explain":"One substance breaks into two when heated."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which is a displacement reaction?","choices":["iron + copper sulfate → iron sulfate + copper","methane + oxygen → carbon dioxide + water","calcium carbonate → calcium oxide + carbon dioxide"],"answer":0,"hint":"One metal swaps places with another.","explain":"Iron takes copper's place in the compound because iron is more reactive."},{"type":"numeric","id":"p2","prompt":"Heating {=a+b} g of calcium carbonate leaves {a} g of calcium oxide. How many grams of carbon dioxide escaped?","answer":"b","hint":"Mass is conserved: the missing mass is the gas.","explain":"{=a+b} − {a} = {b} g of carbon dioxide.","params":{"a":[10,30],"b":[5,25]}},{"type":"numeric","id":"p3","prompt":"{a} g of magnesium is oxidised and gains {b} g of oxygen. What mass of magnesium oxide forms, in grams?","answer":"a+b","hint":"The oxide contains both.","explain":"{a} + {b} = {=a+b} g of magnesium oxide.","params":{"a":[2,12],"b":[1,8]}},{"type":"mc","id":"p4","prompt":"Which type of reaction uses heat to break one substance into two or more?","choices":["Thermal decomposition","Displacement","Combustion"],"answer":0,"hint":"'Thermal' means heat.","explain":"Thermal decomposition: heat breaks a compound down."}],"explain":{"kid":["Chemists sort reactions into types. Combustion is burning. A fuel reacts with oxygen and gives out heat and light.","Oxidation means a substance gains oxygen, like iron when it rusts. Thermal decomposition means heat breaks one substance into simpler ones. Displacement means a more reactive metal pushes a less reactive metal out of its compound."],"adult":["Combustion is fast oxidation that gives out energy. Methane burns to make carbon dioxide and water. Rusting is slow oxidation of iron. It needs both air and water.","In thermal decomposition, heat splits one compound. Limestone (calcium carbonate) gives lime and carbon dioxide. In displacement, iron pushes copper out of copper sulfate, because iron is more reactive."]},"familyTip":"Spot reactions at home: the gas hob (combustion), a rusty bike chain (oxidation), baking powder in a hot oven (thermal decomposition)."},"mt_1hgck6ucII":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Water boiling is a…","choices":["physical change","chemical change"],"answer":0,"hint":"Is the steam still water?","explain":"Steam is still water, so it is a physical change."},{"type":"mc","id":"m2","prompt":"Frying an egg is a…","choices":["chemical change","physical change"],"answer":0,"hint":"Can it be unfried?","explain":"New substances form in the egg, and it can't be undone."},{"type":"numeric","id":"m3","prompt":"{a} g of magnesium burns in a closed jar and uses {b} g of oxygen. What mass of magnesium oxide forms, in grams?","answer":"a+b","hint":"Mass is conserved in a closed jar.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[2,12],"b":[1,8]}},{"type":"numeric","id":"m4","prompt":"{a} g of sugar dissolves in {b} g of tea. What does the sweet tea weigh, in grams?","answer":"a+b","hint":"Add the masses.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[3,15],"b":[150,300]}},{"type":"mc","id":"m5","prompt":"Why is dissolving salt a physical change?","choices":["The salt is still there: evaporate the water and it comes back","A new substance forms","It can never be undone"],"answer":0,"hint":"Can you get the salt back?","explain":"Evaporating the water gets the salt back, so no new substance formed."},{"type":"mc","id":"m6","prompt":"When wood burns in an open fire, the ash weighs less than the wood. Why?","choices":["Gases escaped into the air","Mass was destroyed","Ash is lighter than air"],"answer":0,"hint":"Where did the missing mass go?","explain":"Carbon dioxide and water vapour went into the air; the mass still exists."},{"type":"mc","id":"m7","prompt":"Which change makes a new substance?","choices":["Rusting","Melting","Freezing"],"answer":0,"hint":"Changes of state don't make new substances.","explain":"Rust is a new substance, iron oxide."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which is a chemical change?","choices":["Toast going brown","Butter melting","Sugar dissolving"],"answer":0,"hint":"Is a new substance made?","explain":"Browning makes new substances; the others are physical changes."},{"type":"numeric","id":"p2","prompt":"{a} g of salt dissolves in {b} g of water. What is the mass of the solution, in grams?","answer":"a+b","hint":"Dissolving is physical: nothing is lost.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[5,40],"b":[50,200]}},{"type":"numeric","id":"p3","prompt":"{a} g of ice melts. What is the mass of the water, in grams?","answer":"a","hint":"Melting changes state, not mass.","explain":"Melting is a physical change, so the water still weighs {a} g.","params":{"a":[5,90]}},{"type":"mc","id":"p4","prompt":"Which is a sign of a chemical change?","choices":["A gas is given off and a new colour appears","The substance changes shape","Ice turns into water"],"answer":0,"hint":"Look for signs of a new substance.","explain":"Fizzing and a new colour show a new substance has formed."}],"explain":{"kid":["In a physical change, the stuff stays the same. Melted ice is still water. You can usually change it back.","In a chemical change, new substances are made. Burning wood makes ash, smoke and gases. Signs include a new colour, fizzing, light or heat. In both kinds of change, the total mass stays the same."],"adult":["Physical changes alter state, shape or mixing, but the particles themselves are unchanged, so they are usually reversible: melting, dissolving, evaporating.","Chemical changes rearrange atoms into new substances and are usually hard to reverse. Mass is conserved in both. If a gas escapes from an open container, the mass seems to drop, but the gas still has mass."]},"familyTip":"Cook together and name each change: butter melting (physical), toast browning (chemical), sugar dissolving in tea (physical)."},"mt_rbPioPELM1":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A bike chain rusting is…","choices":["irreversible","reversible"],"answer":0,"hint":"Can rust turn back into shiny iron by itself?","explain":"Rust is a new material, so the change is irreversible."},{"type":"mc","id":"m2","prompt":"What does iron need to rust?","choices":["Water and oxygen","Only heat","Only sunlight"],"answer":0,"hint":"Think of a wet nail in air.","explain":"Rusting needs both water and oxygen."},{"type":"numeric","id":"m3","prompt":"{a} g of candle wax is melted and then left to set. What mass of wax is there now, in grams?","answer":"a","hint":"Melting and setting are reversible.","explain":"No new material formed, so there is still {a} g.","params":{"a":[10,90]}},{"type":"numeric","id":"m4","prompt":"{a} g of chalk reacts with {b} g of acid in a sealed bottle. What do the contents weigh afterwards, in grams?","answer":"a+b","hint":"Sealed: nothing escapes.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[2,10],"b":[20,60]}},{"type":"mc","id":"m5","prompt":"How could you get sugar back after dissolving it in water?","choices":["Evaporate the water","Burn it","You can't"],"answer":0,"hint":"Dissolving is reversible.","explain":"Let the water evaporate and the sugar is left behind."},{"type":"mc","id":"m6","prompt":"Which is NOT a sign of an irreversible change?","choices":["Changing shape","A new smell","Bubbles of gas"],"answer":0,"hint":"Squashing clay doesn't make a new material.","explain":"A change of shape makes nothing new."},{"type":"mc","id":"m7","prompt":"Cooking an egg is irreversible because…","choices":["new substances form in the egg","the egg gets hot","the shell cracks"],"answer":0,"hint":"Can you uncook it?","explain":"Heat changes the egg into new substances that can't change back."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which change is irreversible?","choices":["Burning paper","Melting butter","Freezing juice"],"answer":0,"hint":"Which one makes new materials?","explain":"Burning makes ash and gases, which cannot turn back into paper."},{"type":"numeric","id":"p2","prompt":"A {a} g ice lolly melts. How much does the juice weigh, in grams?","answer":"a","hint":"Melting is reversible: nothing is lost.","explain":"The juice still weighs {a} g.","params":{"a":[20,90]}},{"type":"numeric","id":"p3","prompt":"{a} g of vinegar and {b} g of baking soda fizz inside a sealed bag. What do the bag's contents weigh afterwards, in grams?","answer":"a+b","hint":"The gas is trapped in the bag.","explain":"Nothing can escape, so it is {a} + {b} = {=a+b} g.","params":{"a":[20,80],"b":[2,10]}},{"type":"mc","id":"p4","prompt":"Which clue shows a new material has formed?","choices":["Bubbles of a new gas","It changed shape","It got wet"],"answer":0,"hint":"Look for something new.","explain":"A new gas means a new material: an irreversible change."}],"explain":{"kid":["Some changes can be undone. Melted chocolate sets again when it cools. These are reversible changes.","Other changes make new materials that cannot turn back. Burnt toast stays burnt. Rust stays rust. Vinegar and baking soda fizz and make a gas. These are irreversible changes."],"adult":["Irreversible changes are chemical: new materials form. Clues include fizzing (a gas forms), a lasting colour change, heat or light given out, or a new smell.","Burning needs oxygen and makes new substances such as carbon dioxide, water and ash. Rusting needs iron, water and oxygen. Acids react with carbonates to release carbon dioxide."]},"familyTip":"Make a mini volcano with vinegar and bicarbonate of soda. Ask: can we get the vinegar back? Why not?"},"mt_Ge4Wtg6QMM":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Why are pan handles often plastic?","choices":["Plastic is a thermal insulator","Plastic conducts heat well","Plastic is magnetic"],"answer":0,"hint":"You hold the handle.","explain":"Plastic doesn't let heat through easily, so the handle stays cool."},{"type":"mc","id":"m2","prompt":"Which is transparent?","choices":["Clear glass","Wood","Steel"],"answer":0,"hint":"Can you see clearly through it?","explain":"Clear glass lets light straight through."},{"type":"mc","id":"m3","prompt":"Which dissolves in water?","choices":["Sugar","Sand","Plastic"],"answer":0,"hint":"Which one disappears when stirred?","explain":"Sugar is soluble; sand and plastic are not."},{"type":"mc","id":"m4","prompt":"Copper is used for wires because it…","choices":["conducts electricity and bends easily","is magnetic","dissolves in water"],"answer":0,"hint":"Two properties a wire needs.","explain":"Good conductor, and flexible enough to bend."},{"type":"numeric","id":"m5","prompt":"Of {n} spoons, {k} are steel and the rest are wooden. How many are electrical insulators?","answer":"n-k","hint":"Wood is an insulator.","explain":"{n} − {k} = {=n-k} wooden spoons.","params":{"n":[6,15],"k":[1,5]}},{"type":"numeric","id":"m6","prompt":"A magnet picks up {a} iron paper clips and {b} steel pins. How many magnetic objects is that?","answer":"a+b","hint":"Iron and steel are both magnetic.","explain":"{a} + {b} = {=a+b}.","params":{"a":[2,9],"b":[2,9]}},{"type":"mc","id":"m7","prompt":"Which test shows if a material conducts electricity?","choices":["Put it in a circuit with a bulb","Hold a magnet near it","Drop it in water"],"answer":0,"hint":"Electricity needs a circuit.","explain":"If the bulb lights, the material conducts."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which material conducts electricity?","choices":["Copper","Plastic","Wood"],"answer":0,"hint":"Wires are made of it.","explain":"Copper is a metal and a good electrical conductor."},{"type":"mc","id":"p2","prompt":"Which object is attracted to a magnet?","choices":["An iron nail","An aluminium can","A copper coin"],"answer":0,"hint":"Only some metals are magnetic.","explain":"Iron is magnetic; aluminium and copper are not."},{"type":"numeric","id":"p3","prompt":"In a circuit test of {n} materials, {k} made the bulb light. How many are electrical insulators?","answer":"n-k","hint":"Insulators don't light the bulb.","explain":"{n} − {k} = {=n-k} insulators.","params":{"n":[6,12],"k":[1,5]}},{"type":"numeric","id":"p4","prompt":"{a} g of salt dissolves in some water, and the solution weighs {=a+b} g. What did the water weigh, in grams?","answer":"b","hint":"Dissolving keeps all the mass.","explain":"{=a+b} − {a} = {b} g of water.","params":{"a":[5,30],"b":[50,150]}}],"explain":{"kid":["Materials have properties. Some are hard and some are soft. Some let light through. Some dissolve in water.","Metals let electricity and heat pass through them easily, so we call them conductors. Plastic, wood and rubber do not, so we call them insulators. Iron and steel are pulled by magnets, but most other metals are not."],"adult":["Group materials by tests, not guesses: a simple circuit with a bulb tests electrical conductivity, a magnet tests magnetism, and stirring in water tests solubility.","Properties decide uses. Copper is used for wires because it conducts electricity and bends easily. Pan handles are plastic or wood because they are thermal insulators."]},"familyTip":"Hunt the kitchen with a fridge magnet: which metal things does it stick to? (Steel cans yes, aluminium foil no.)"},"mt_htAYR-iCFF":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"In which state are particles in a regular pattern?","choices":["Solid","Liquid","Gas"],"answer":0,"hint":"Think of a crystal.","explain":"Solids have a regular arrangement."},{"type":"mc","id":"m2","prompt":"Which state flows and takes the shape of its container but keeps its volume?","choices":["Liquid","Solid","Gas"],"answer":0,"hint":"Pour it into a jug.","explain":"A liquid flows but its particles stay close together."},{"type":"mc","id":"m3","prompt":"Why can a gas be squashed?","choices":["There are big gaps between its particles","Its particles are soft","It has no particles"],"answer":0,"hint":"Look at the spacing.","explain":"The gaps let the particles be pushed closer together."},{"type":"numeric","id":"m4","prompt":"A solid with {r} rows of {c} particles melts. How many particles are in the liquid?","answer":"r*c","hint":"Melting doesn't add or remove particles.","explain":"Still {r} × {c} = {=r*c} particles.","params":{"r":[2,6],"c":[3,8]}},{"type":"numeric","id":"m5","prompt":"A sealed balloon holds {n} particles. It warms up in the sun. How many particles are there now?","answer":"n","hint":"Nothing gets in or out.","explain":"Still {n} particles; they just move faster.","params":{"n":[10,40]}},{"type":"mc","id":"m6","prompt":"What should arrows on a gas diagram show?","choices":["Fast movement in random directions","The particles growing","Particles standing still"],"answer":0,"hint":"Gas particles never stop.","explain":"Arrows show fast, random motion."},{"type":"mc","id":"m7","prompt":"What does heating do to particles?","choices":["Makes them move faster","Makes them bigger","Makes them heavier"],"answer":0,"hint":"Energy goes into movement.","explain":"Hotter particles move faster."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which diagram shows a gas?","choices":["A few particles far apart, with arrows","Particles in neat touching rows","Particles touching but jumbled"],"answer":0,"hint":"Gases have big gaps.","explain":"Gas particles are far apart and move fast."},{"type":"mc","id":"p2","prompt":"When ice melts, do the particles get bigger?","choices":["No: they move more but stay the same size","Yes","They disappear"],"answer":0,"hint":"Heating changes movement, not size.","explain":"The particles are the same; they just move more freely."},{"type":"numeric","id":"p3","prompt":"A solid diagram has {r} rows of {c} particles. How many particles is that?","answer":"r*c","hint":"Rows × particles in each row.","explain":"{r} × {c} = {=r*c} particles.","params":{"r":[2,6],"c":[3,8]}},{"type":"numeric","id":"p4","prompt":"A sealed box of gas has {n} particles. The box is heated. How many particles are in it now?","answer":"n","hint":"Sealed: none get in or out.","explain":"Heating makes them faster, but there are still {n}.","params":{"n":[8,30]}}],"explain":{"kid":["Everything is made of tiny particles, far too small to see. We draw them as small circles.","In a solid, draw the circles touching, in neat rows. In a liquid, draw them touching but jumbled. In a gas, draw just a few, far apart, with arrows to show they move fast."],"adult":["A good diagram shows arrangement, spacing and movement. Solid: regular and touching, vibrating in place. Liquid: touching but random, sliding past each other. Gas: far apart and random, moving quickly in all directions.","Keep the particles the same size in every state. Heating makes particles move faster; it does not make them bigger."]},"familyTip":"Use coins on a table: neat rows for a solid, a jumbled touching heap for a liquid, a few spread across the table for a gas."},"mt_MVovx37Xct":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A tea cosy should be made of a…","choices":["thermal insulator","electrical conductor","transparent material"],"answer":0,"hint":"It keeps the pot warm.","explain":"It must stop heat escaping: a thermal insulator."},{"type":"mc","id":"m2","prompt":"Rigid means…","choices":["it does not bend easily","it bends easily","it dissolves"],"answer":0,"hint":"The opposite of flexible.","explain":"Rigid is the opposite of flexible."},{"type":"mc","id":"m3","prompt":"Which is opaque?","choices":["A wooden door","A clear plastic bottle","A glass of water"],"answer":0,"hint":"No light gets through.","explain":"Wood lets no light through."},{"type":"mc","id":"m4","prompt":"An electrical conductor…","choices":["lets electricity flow through it","blocks electricity","is always magnetic"],"answer":0,"hint":"Think of a wire.","explain":"Conductors let electricity flow."},{"type":"numeric","id":"m5","prompt":"A test found {k} of {n} metals were magnetic. How many were non-magnetic?","answer":"n-k","hint":"Take the magnetic ones away.","explain":"{n} − {k} = {=n-k}.","params":{"n":[5,10],"k":[1,4]}},{"type":"numeric","id":"m6","prompt":"{a} g of insoluble sand is stirred into {b} g of water, then filtered out. What mass of sand is caught in the filter, in grams?","answer":"a","hint":"Insoluble: it doesn't dissolve.","explain":"All {a} g of sand is caught.","params":{"a":[5,50],"b":[100,200]}},{"type":"mc","id":"m7","prompt":"Which pair are opposites?","choices":["soluble / insoluble","transparent / translucent","flexible / magnetic"],"answer":0,"hint":"One word means 'not' the other.","explain":"Insoluble means not soluble."}]},"practice":[{"type":"mc","id":"p1","prompt":"Frosted glass lets light through, but you can't see clearly through it. It is…","choices":["translucent","transparent","opaque"],"answer":0,"hint":"Some light, blurry view.","explain":"Some light gets through but the view is blurred: translucent."},{"type":"mc","id":"p2","prompt":"Which word means 'does not dissolve'?","choices":["insoluble","soluble","flexible"],"answer":0,"hint":"'In-' means not.","explain":"Insoluble means it does not dissolve."},{"type":"numeric","id":"p3","prompt":"Out of {n} materials, {k} are opaque. How many let at least some light through?","answer":"n-k","hint":"Opaque ones let no light through.","explain":"{n} − {k} = {=n-k}.","params":{"n":[6,12],"k":[1,5]}},{"type":"numeric","id":"p4","prompt":"{a} g of soluble sugar is stirred into {b} g of water. What is the total mass, in grams?","answer":"a+b","hint":"Dissolving keeps all the mass.","explain":"{a} + {b} = {=a+b} g.","params":{"a":[5,30],"b":[100,250]}}],"explain":{"kid":["Scientists use exact words for properties. Transparent means you can see clearly through it. Translucent lets some light through, but things look blurry. Opaque lets no light through.","There are more words in pairs. A conductor lets heat or electricity through, and an insulator does not. Soluble means it dissolves, and insoluble means it does not. Flexible means it bends, and rigid means it does not."],"adult":["Precise words make comparisons clear: 'thermal insulator' says more than 'keeps warm'. Pair each word with its opposite: conductor/insulator, soluble/insoluble, flexible/rigid, magnetic/non-magnetic.","Use the words to justify a choice. A window needs a transparent, rigid, waterproof material, so glass is used. A tea cosy needs a flexible thermal insulator, so wool or fabric works."]},"familyTip":"Shine a torch through things at home: a glass, a tissue, a book. Name each one: transparent, translucent or opaque."},"mt_P8Da-_zGBG":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"What is the relative mass of an electron?","choices":["Almost 0 (about 1/1840)","1","−1"],"answer":0,"hint":"Much lighter than a proton.","explain":"About 1/1840, so almost 0."},{"type":"numeric","id":"m2","prompt":"An atom has mass number {m} and {p} protons. How many neutrons does it have?","answer":"m-p","hint":"Neutrons = mass number − protons.","explain":"{m} − {p} = {=m-p} neutrons.","params":{"p":[1,20],"m":[2,45]},"where":"m>=p && m<=2*p+4"},{"type":"numeric","id":"m3","prompt":"An ion has {p} protons and {=p-d} electrons. What is its charge?","answer":"d","hint":"Charge = protons − electrons.","explain":"{p} − {=p-d} = +{d}, so the charge is {d}+.","params":{"p":[3,20],"d":[1,3]}},{"type":"mc","id":"m4","prompt":"An atom has no overall charge because…","choices":["it has equal numbers of protons and electrons","it has no protons","neutrons cancel the charge"],"answer":0,"hint":"+1s and −1s.","explain":"Equal numbers of +1 and −1 charges cancel out."},{"type":"mc","id":"m5","prompt":"What is the relative charge of a proton?","choices":["+1","0","−1"],"answer":0,"hint":"Protons are positive.","explain":"+1."},{"type":"mc","id":"m6","prompt":"Which two particles are in the nucleus?","choices":["Protons and neutrons","Protons and electrons","Neutrons and electrons"],"answer":0,"hint":"Electrons are in shells.","explain":"Protons and neutrons."},{"type":"numeric","id":"m7","prompt":"A nucleus has {p} protons and {n} neutrons. What is the nucleus's total relative charge?","answer":"p","hint":"Only the protons are charged.","explain":"{p} protons × +1 = +{p}, so the charge is {p}.","params":{"p":[1,20],"n":[0,22]}}]},"practice":[{"type":"mc","id":"p1","prompt":"Which particle has no charge?","choices":["Neutron","Proton","Electron"],"answer":0,"hint":"'Neutral' sounds like…","explain":"The neutron is neutral."},{"type":"numeric","id":"p2","prompt":"An atom has {p} protons and {n} neutrons. What is its mass number?","answer":"p+n","hint":"Mass number = protons + neutrons.","explain":"{p} + {n} = {=p+n}.","params":{"p":[1,20],"n":[0,22]}},{"type":"numeric","id":"p3","prompt":"A neutral atom has {p} protons. How many electrons does it have?","answer":"p","hint":"Neutral means the charges balance.","explain":"It has {p} electrons to balance {p} protons.","params":{"p":[1,20]}},{"type":"mc","id":"p4","prompt":"Where is almost all of an atom's mass?","choices":["In the nucleus","In the electron shells","Spread out evenly"],"answer":0,"hint":"Electrons are almost massless.","explain":"Protons and neutrons are in the nucleus, and they carry the mass."}],"explain":{"kid":["An atom has a tiny nucleus in the middle. It holds protons and neutrons. Electrons move around the outside in shells.","A proton has a charge of +1. An electron has a charge of −1. A neutron has no charge. Protons and neutrons each have a mass of 1. An electron is so light that we say its mass is almost 0."],"adult":["Relative charges: proton +1, neutron 0, electron −1. Relative masses: proton 1, neutron 1, electron about 1/1840.","Atoms are neutral because they have equal numbers of protons and electrons. Mass number = protons + neutrons. An ion forms when an atom gains or loses electrons: lose one and the charge is +1."]},"familyTip":"Make a table with three rows (proton, neutron, electron) and two columns (charge, mass). Cover it and test each other."},"mt_AN2kJE6I0s":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which pH is neutral?","choices":["7","0","14"],"answer":0,"hint":"The middle of the scale.","explain":"pH 7 is neutral."},{"type":"mc","id":"m2","prompt":"Which ions do acids release in water?","choices":["H⁺","OH⁻","Na⁺"],"answer":0,"hint":"Hydrogen ions.","explain":"Acids release H⁺ ions."},{"type":"mc","id":"m3","prompt":"acid + alkali → ?","choices":["salt + water","gas + oxygen","acid + water"],"answer":0,"hint":"Neutralisation.","explain":"They make a salt and water."},{"type":"numeric","id":"m4","prompt":"Solution A is pH {a} and B is pH {=a+d}. How many times more hydrogen ions does A have?","answer":"10**d","hint":"Lower pH means more H⁺; each step is × 10.","explain":"{d} steps: {=10**d} times more.","params":{"a":[1,5],"d":[1,3]}},{"type":"mc","id":"m5","prompt":"Which is most likely to be pH 13?","choices":["Oven cleaner","Lemon juice","Pure water"],"answer":0,"hint":"Strong alkalis clean grease.","explain":"Oven cleaner is a strong alkali."},{"type":"numeric","id":"m6","prompt":"Adding alkali drop by drop, an acid turns green after {a} drops. How many drops would neutralise twice as much of the same acid?","answer":"2*a","hint":"Twice the acid needs twice the alkali.","explain":"2 × {a} = {=2*a} drops.","params":{"a":[5,30]}},{"type":"mc","id":"m7","prompt":"Litmus paper can tell you…","choices":["only whether it is acid or alkali","the exact pH number","the temperature"],"answer":0,"hint":"Litmus has only two colours.","explain":"Red or blue: acid or alkali, not the number."}]},"practice":[{"type":"mc","id":"p1","prompt":"pH 2 is…","choices":["strongly acidic","neutral","alkaline"],"answer":0,"hint":"Far below 7.","explain":"pH 2 is well below 7: a strong acid."},{"type":"mc","id":"p2","prompt":"What colour is universal indicator in pure water?","choices":["Green","Red","Purple"],"answer":0,"hint":"Pure water is pH 7.","explain":"Neutral pH 7 shows green."},{"type":"numeric","id":"p3","prompt":"A solution changes from pH {a} to pH {=a-d}. How many times more hydrogen ions does it have now?","answer":"10**d","hint":"Each pH step is × 10.","explain":"{d} steps of × 10 make {=10**d} times more.","params":{"a":[5,9],"d":[1,3]}},{"type":"numeric","id":"p4","prompt":"{a} cm³ of acid is exactly neutralised by {b} cm³ of alkali. What volume of solution is there, in cm³?","answer":"a+b","hint":"Add the volumes.","explain":"{a} + {b} = {=a+b} cm³.","params":{"a":[5,50],"b":[5,50]}}],"explain":{"kid":["The pH scale runs from 0 to 14. Below 7 is acid, 7 is neutral, and above 7 is alkali.","An indicator changes colour to show pH. Universal indicator is red in strong acid, green when neutral, and purple in strong alkali. Lemon juice is an acid. Soap is an alkali."],"adult":["Acids release hydrogen ions (H⁺) in water; alkalis release hydroxide ions (OH⁻). The more H⁺, the lower the pH. Each step of 1 on the scale is a tenfold change in H⁺.","Neutralisation: acid + alkali → salt + water, because H⁺ and OH⁻ join to make water. Litmus only says acid or alkali; universal indicator or a pH probe gives a number."]},"familyTip":"Make red-cabbage indicator: boil chopped red cabbage, cool and strain. Test vinegar, soap and baking soda and compare the colours."},"mt_UoqUPI_uNz":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"In an exothermic reaction the products have…","choices":["less energy than the reactants","more energy than the reactants","the same energy"],"answer":0,"hint":"Energy went out.","explain":"Energy left, so the products have less."},{"type":"mc","id":"m2","prompt":"A hand warmer uses a reaction that is…","choices":["exothermic","endothermic"],"answer":0,"hint":"It warms your hand.","explain":"It gives out heat: exothermic."},{"type":"numeric","id":"m3","prompt":"The reactants have {a} kJ of energy and the products have {=a-d} kJ. How much energy is given out, in kJ?","answer":"d","hint":"Reactants − products.","explain":"{a} − {=a-d} = {d} kJ given out.","params":{"a":[100,200],"d":[10,90]}},{"type":"numeric","id":"m4","prompt":"A cold pack drops from {a} °C to {b} °C. How many degrees did it fall?","answer":"a-b","hint":"Start − end.","explain":"{a} − {b} = {=a-b} degrees.","params":{"a":[18,25],"b":[2,12]}},{"type":"mc","id":"m5","prompt":"What is activation energy?","choices":["The energy needed to start a reaction","The energy given out at the end","The energy of the products"],"answer":0,"hint":"The hump on the profile.","explain":"It is the energy needed to get the reaction going."},{"type":"mc","id":"m6","prompt":"Why does sherbet feel cold on your tongue?","choices":["Its reaction takes in heat from your tongue","It is kept in a freezer","It is exothermic"],"answer":0,"hint":"Endo means 'in'.","explain":"The fizzing reaction is endothermic, so it takes in heat."},{"type":"mc","id":"m7","prompt":"On the energy profile of an endothermic reaction, the products are…","choices":["higher than the reactants","lower than the reactants","level with the reactants"],"answer":0,"hint":"Energy was taken in.","explain":"They have gained energy, so they sit higher."}]},"practice":[{"type":"mc","id":"p1","prompt":"The temperature rises from 20 °C to 31 °C. The reaction is…","choices":["exothermic","endothermic"],"answer":0,"hint":"Did it get warmer?","explain":"It got warmer, so energy was given out: exothermic."},{"type":"numeric","id":"p2","prompt":"A reaction starts at {a} °C and ends at {=a+d} °C. By how many degrees did it warm up?","answer":"d","hint":"End − start.","explain":"{=a+d} − {a} = {d} degrees, so it is exothermic.","params":{"a":[15,25],"d":[2,20]}},{"type":"numeric","id":"p3","prompt":"The temperature falls from {a} °C to {=a-d} °C. By how many degrees did it fall?","answer":"d","hint":"Start − end.","explain":"{a} − {=a-d} = {d} degrees, so it is endothermic.","params":{"a":[18,25],"d":[2,12]}},{"type":"mc","id":"p4","prompt":"Which is endothermic?","choices":["Heating limestone to break it down","Burning methane","Neutralising an acid"],"answer":0,"hint":"Which one needs heat put in all the time?","explain":"Thermal decomposition takes in heat."}],"explain":{"kid":["Some reactions give out heat. They are called exothermic, and the mixture gets warmer. Burning is exothermic.","Some reactions take in heat. They are called endothermic, and the mixture gets colder. Sherbet fizzing on your tongue feels cool because it takes in heat."],"adult":["Exothermic: energy goes out to the surroundings, so the temperature rises. The products have less energy than the reactants. Examples: burning, neutralisation, hand warmers.","Endothermic: energy is taken in, so the temperature falls. The products have more energy. Examples: heating limestone, photosynthesis and cold packs. Every reaction needs some energy to start. That is the hump on the energy profile."]},"familyTip":"Feel a hand warmer, then a cold pack. Which gives energy to your hand, and which takes it away?"},"mt_5r47Pvstyn":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A window is made of…","choices":["glass","a window","a door"],"answer":0,"hint":"What is it made of?","explain":"Windows are made of glass."},{"type":"mc","id":"m2","prompt":"Can a spoon be made of wood?","choices":["Yes","No"],"answer":0,"hint":"Think of a cooking spoon.","explain":"Yes, wooden spoons are common."},{"type":"mc","id":"m3","prompt":"Which pair is (object, material)?","choices":["(chair, wood)","(wood, chair)","(metal, glass)"],"answer":0,"hint":"Thing first.","explain":"A chair is the object; wood is the material."},{"type":"numeric","id":"m4","prompt":"There are {n} wooden blocks and {m} plastic blocks. How many blocks?","answer":"n+m","hint":"Add.","explain":"{n} + {m} = {=n+m}.","params":{"n":[2,6],"m":[1,5]}},{"type":"numeric","id":"m5","prompt":"{n} toys are metal. {m} are not. How many toys?","answer":"n+m","hint":"Add both.","explain":"{=n+m} toys.","params":{"n":[1,6],"m":[1,6]}},{"type":"mc","id":"m6","prompt":"Is plastic an object or a material?","choices":["A material","An object"],"answer":0,"hint":"Can you make things from it?","explain":"Plastic is a material."},{"type":"mc","id":"m7","prompt":"A metal spoon and a wooden spoon are both…","choices":["spoons","metal","wood"],"answer":0,"hint":"Same object.","explain":"Both are spoons, made of different materials."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which is a material?","choices":["wood","chair","table"],"answer":0,"hint":"What things are made of.","explain":"Wood is a material; chairs and tables are objects."},{"type":"mc","id":"p2","prompt":"Which is an object?","choices":["spoon","metal","plastic"],"answer":0,"hint":"A thing you can use.","explain":"A spoon is an object."},{"type":"numeric","id":"p3","prompt":"{n} spoons are made of metal and {m} of wood. How many spoons?","answer":"n+m","hint":"Add them.","explain":"{n} + {m} = {=n+m} spoons.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"p4","prompt":"{n} cups are plastic and {m} are glass. How many glass cups?","answer":"m","hint":"Just the glass ones.","explain":"{m} are glass.","params":{"n":[1,5],"m":[1,5]}}],"explain":{"kid":["A spoon is an object. It can be made of metal, wood or plastic. Those are materials.","It is still a spoon, whatever it is made of."],"adult":["Children often mix up objects (spoon, chair, window) with materials (metal, wood, glass). Ask 'what is it?' for the object and 'what is it made of?' for the material.","The same object can be made of different materials, and the same material can make many objects. That idea leads to choosing materials for a job."]},"familyTip":"Pick three things in the kitchen. For each, say the object and the material: 'a cup, made of china'."},"mt_ZAJvTcroFO":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A T-shirt is made of…","choices":["fabric","metal","rock"],"answer":0,"hint":"Soft, you wear it.","explain":"Clothes are fabric."},{"type":"mc","id":"m2","prompt":"A book's pages are made of…","choices":["paper","glass","plastic"],"answer":0,"hint":"Thin, you turn them.","explain":"Pages are paper."},{"type":"mc","id":"m3","prompt":"A wall is often made of…","choices":["brick","fabric","paper"],"answer":0,"hint":"Strong blocks.","explain":"Walls are often brick."},{"type":"numeric","id":"m4","prompt":"{n} cups are glass and {m} are plastic. How many cups?","answer":"n+m","hint":"Add.","explain":"{=n+m} cups.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"m5","prompt":"A pencil is made of {n} parts. Each part is one material. How many materials?","answer":"n","hint":"One each.","explain":"{n} parts, so {n} materials.","params":{"n":[2,5]}},{"type":"mc","id":"m6","prompt":"A spoon can be made of…","choices":["metal, wood or plastic","only glass","only paper"],"answer":0,"hint":"Think of your kitchen.","explain":"Spoons come in metal, wood and plastic."},{"type":"mc","id":"m7","prompt":"Which is NOT a material?","choices":["a table","wood","glass"],"answer":0,"hint":"Things vs stuff.","explain":"A table is an object."}]},"practice":[{"type":"mc","id":"p1","prompt":"A key is usually made of…","choices":["metal","glass","paper"],"answer":0,"hint":"Hard and shiny.","explain":"Keys are metal."},{"type":"mc","id":"p2","prompt":"A window is made of…","choices":["glass","wood","fabric"],"answer":0,"hint":"You can see through it.","explain":"Windows are glass."},{"type":"numeric","id":"p3","prompt":"You find {n} wooden things and {m} metal things. How many things?","answer":"n+m","hint":"Add.","explain":"{n} + {m} = {=n+m}.","params":{"n":[1,6],"m":[1,6]}},{"type":"numeric","id":"p4","prompt":"{n} of your {=n+m} toys are plastic. How many are not plastic?","answer":"m","hint":"Take away.","explain":"{=n+m} − {n} = {m}.","params":{"n":[1,5],"m":[1,5]}}],"explain":{"kid":["Look around. A door is wood. A window is glass. A key is metal. A bag can be fabric or plastic.","Each of these is a material."],"adult":["The core list for young children is wood, plastic, glass, metal, water, rock, brick, paper, card and fabric. Naming them gives words for later work on properties.","Point out that one object can use several materials: a pencil is wood with graphite inside and a metal end."]},"familyTip":"Go on a material hunt at home. Find something made of wood, metal, glass, plastic and fabric."},"mt_auVZZEuXjs":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A coat that keeps rain out is…","choices":["waterproof","absorbent","transparent"],"answer":0,"hint":"Water stays out.","explain":"It keeps water out: waterproof."},{"type":"mc","id":"m2","prompt":"A metal spoon is…","choices":["shiny and stiff","soft and bendy","dull and absorbent"],"answer":0,"hint":"Test it in your mind.","explain":"Metal spoons are shiny and stiff."},{"type":"mc","id":"m3","prompt":"A towel is…","choices":["soft and absorbent","hard and shiny","waterproof"],"answer":0,"hint":"It dries you.","explain":"Towels soak up water and feel soft."},{"type":"numeric","id":"m4","prompt":"{n} of {=n+m} materials bend. How many do not bend?","answer":"m","hint":"Take away.","explain":"{=n+m} − {n} = {m}.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"m5","prompt":"You did {n} tests on each of {m} materials. How many tests?","answer":"n*m","hint":"Groups of tests.","explain":"{n} × {m} = {=n*m}.","params":{"n":[2,3],"m":[2,4]}},{"type":"mc","id":"m6","prompt":"The opposite of rough is…","choices":["smooth","soft","shiny"],"answer":0,"hint":"Run your hand on it.","explain":"Rough and smooth are opposites."},{"type":"mc","id":"m7","prompt":"Which test checks if a material is waterproof?","choices":["Drip water on it","Bend it","Scratch it"],"answer":0,"hint":"Water test.","explain":"Drip water and see if it soaks in."}]},"practice":[{"type":"mc","id":"p1","prompt":"Water soaks into a sponge. The sponge is…","choices":["absorbent","waterproof","shiny"],"answer":0,"hint":"It soaks up water.","explain":"Soaks up water: absorbent."},{"type":"mc","id":"p2","prompt":"The opposite of stiff is…","choices":["bendy","hard","dull"],"answer":0,"hint":"Can it bend?","explain":"Stiff and bendy are opposites."},{"type":"numeric","id":"p3","prompt":"You test {n} things. {m} are shiny. How many are dull?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[5,9],"m":[1,4]}},{"type":"numeric","id":"p4","prompt":"{n} things are waterproof and {m} are not. How many things?","answer":"n+m","hint":"Add.","explain":"{=n+m}.","params":{"n":[1,5],"m":[1,5]}}],"explain":{"kid":["Is it hard or soft? Is it shiny or dull? Does it bend? Does water soak in?","These words tell us what a material is like."],"adult":["Property words come in opposite pairs: hard/soft, stiff/bendy (flexible), shiny/dull, rough/smooth, waterproof/absorbent, transparent/opaque. Testing is better than guessing.","Let children test: bend it, drip water on it, scratch it with a coin, shine a torch at it. Then name the property in a sentence: 'foil is shiny and bendy'."]},"familyTip":"Test a sock, a spoon and a plastic bag. Is each one bendy? Waterproof? Shiny?"},"mt_rTn43s8RNX":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Why is a towel made of fabric?","choices":["Fabric soaks up water","Fabric is see-through","Fabric is shiny"],"answer":0,"hint":"A towel dries you.","explain":"Fabric is absorbent."},{"type":"mc","id":"m2","prompt":"Why is a saucepan made of metal?","choices":["Metal is strong and lets heat through","Metal is soft","Metal soaks up water"],"answer":0,"hint":"It goes on the cooker.","explain":"Metal is strong and conducts heat."},{"type":"mc","id":"m3","prompt":"A chocolate teapot is a bad idea because…","choices":["chocolate melts when hot","chocolate is see-through","chocolate is too hard"],"answer":0,"hint":"Hot tea!","explain":"It would melt."},{"type":"numeric","id":"m4","prompt":"{n} kids want raincoats. {m} have one. How many still need one?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[5,9],"m":[1,4]}},{"type":"numeric","id":"m5","prompt":"Each window has {n} panes of glass. How many panes in {m} windows?","answer":"n*m","hint":"Groups.","explain":"{n} × {m} = {=n*m}.","params":{"n":[2,4],"m":[2,3]}},{"type":"mc","id":"m6","prompt":"Which is best for a wellington boot?","choices":["rubber","paper","fabric"],"answer":0,"hint":"Puddles!","explain":"Rubber is waterproof and bendy."},{"type":"mc","id":"m7","prompt":"A good material for a window is…","choices":["glass","wood","brick"],"answer":0,"hint":"See through.","explain":"Glass is transparent."}]},"practice":[{"type":"mc","id":"p1","prompt":"An umbrella should be…","choices":["waterproof","absorbent","see-through"],"answer":0,"hint":"It keeps rain off.","explain":"It must keep water out: waterproof."},{"type":"mc","id":"p2","prompt":"A window needs a material that is…","choices":["see-through","soft","absorbent"],"answer":0,"hint":"You look through it.","explain":"You need to see through it, so glass."},{"type":"numeric","id":"p3","prompt":"You try {n} materials for an umbrella. {m} let water through. How many work?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[5,8],"m":[1,4]}},{"type":"numeric","id":"p4","prompt":"A bag holds {n} books. You need {=n*2}. How many bags?","answer":"2","hint":"Double.","explain":"{=n*2} ÷ {n} = 2 bags.","params":{"n":[2,5]}}],"explain":{"kid":["An umbrella must keep rain off, so we need a waterproof material. Paper would get soggy!","Think about what the job needs, then pick a material that does it."],"adult":["Ask two questions: what does the job need (waterproof, see-through, stiff, soft)? Which material has that property? Then explain the choice with 'because'.","Some materials fail in funny ways: a chocolate teapot melts, a paper umbrella soaks through. These help children reason about properties."]},"familyTip":"Ask: why are windows glass and not wood? Why are towels fabric and not plastic?"},"mt_SwaNNdm_Ks":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"A sock, a scarf and a teddy are all…","choices":["soft","hard","shiny"],"answer":0,"hint":"Squeeze them.","explain":"They are all soft."},{"type":"mc","id":"m2","prompt":"Which could be a sorting rule?","choices":["Does it bend?","Do I like it?","Is it Tuesday?"],"answer":0,"hint":"You can test it.","explain":"You can test if it bends."},{"type":"numeric","id":"m3","prompt":"{n} things are hard and {m} are soft. How many more hard than soft?","answer":"n-m","hint":"Find the difference.","explain":"{n} − {m} = {=n-m}.","params":{"n":[6,10],"m":[1,5]}},{"type":"numeric","id":"m4","prompt":"You have {n} shiny and {m} dull things. How many things?","answer":"n+m","hint":"Add.","explain":"{=n+m}.","params":{"n":[2,6],"m":[2,6]}},{"type":"mc","id":"m5","prompt":"Can a spoon be in the 'hard' group and the 'shiny' group?","choices":["Yes","No"],"answer":0,"hint":"Materials have many properties.","explain":"A metal spoon is both hard and shiny."},{"type":"mc","id":"m6","prompt":"Where does a wooden block go: shiny or dull?","choices":["dull","shiny"],"answer":0,"hint":"Look at it.","explain":"Wood is usually dull."},{"type":"mc","id":"m7","prompt":"Which does NOT belong with glass, metal and foil (shiny)?","choices":["a wool sock","a mirror","a coin"],"answer":0,"hint":"Which is dull?","explain":"Wool is dull."}]},"practice":[{"type":"mc","id":"p1","prompt":"Which goes with a rock, a spoon and a brick?","choices":["a coin (hard)","a sock (soft)","a pillow (soft)"],"answer":0,"hint":"They are all hard.","explain":"A coin is hard too."},{"type":"mc","id":"p2","prompt":"You sort by 'shiny or dull'. Where does a mirror go?","choices":["shiny","dull"],"answer":0,"hint":"Can you see yourself?","explain":"Mirrors are shiny."},{"type":"numeric","id":"p3","prompt":"You sort {n} things into 2 groups. One group has {m}. How many in the other?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[6,10],"m":[1,5]}},{"type":"numeric","id":"p4","prompt":"Group A has {n}, group B has {m}. How many in all?","answer":"n+m","hint":"Add.","explain":"{=n+m}.","params":{"n":[1,6],"m":[1,6]}}],"explain":{"kid":["Put the hard things in one pile and the soft things in another. That is grouping.","You can group the same things a new way, like shiny and dull."],"adult":["Grouping means choosing one property and sorting by it. The same set can be grouped in several ways, which shows that a material has many properties at once.","Ask children to name the rule they used. A good rule is one you can test, like 'does a magnet stick?' or 'does it bend?'."]},"familyTip":"Tip out a box of odds and ends. Sort by one rule, then mix up and sort by another rule."},"mt_1JFUNQDwAJ":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Which fills the whole room?","choices":["a gas","a solid","a liquid"],"answer":0,"hint":"Spreads out.","explain":"Gases spread out to fill the space."},{"type":"mc","id":"m2","prompt":"Which takes the shape of the bottom of its cup?","choices":["a liquid","a solid","nothing"],"answer":0,"hint":"It flows.","explain":"Liquids flow to fill the bottom."},{"type":"mc","id":"m3","prompt":"Steam is water as a…","choices":["gas","solid","liquid"],"answer":0,"hint":"It floats up.","explain":"Steam is a gas."},{"type":"numeric","id":"m4","prompt":"{n} ice cubes melt. How many puddles of water? (one each)","answer":"n","hint":"Each cube makes one.","explain":"{n} puddles.","params":{"n":[2,8]}},{"type":"numeric","id":"m5","prompt":"There are {n} solids and {m} liquids on a table. How many things?","answer":"n+m","hint":"Add.","explain":"{=n+m}.","params":{"n":[1,6],"m":[1,6]}},{"type":"mc","id":"m6","prompt":"A word for a liquid is…","choices":["runny","rigid","hard"],"answer":0,"hint":"It flows.","explain":"Liquids are runny."},{"type":"mc","id":"m7","prompt":"A word for a solid is…","choices":["keeps its shape","pours","fills the room"],"answer":0,"hint":"Ice cube.","explain":"Solids keep their shape."}]},"practice":[{"type":"mc","id":"p1","prompt":"Ice is a…","choices":["solid","liquid","gas"],"answer":0,"hint":"It keeps its shape.","explain":"Ice keeps its shape: solid."},{"type":"mc","id":"p2","prompt":"Milk is a…","choices":["liquid","solid","gas"],"answer":0,"hint":"It pours.","explain":"Milk pours: liquid."},{"type":"numeric","id":"p3","prompt":"You pour {n} cups of juice and {m} cups of milk. How many cups of liquid?","answer":"n+m","hint":"Add.","explain":"{=n+m} cups.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"p4","prompt":"{n} balloons are full of air. {m} pop. How many are left?","answer":"n-m","hint":"Take away.","explain":"{n} − {m} = {=n-m}.","params":{"n":[5,9],"m":[1,4]}}],"explain":{"kid":["A block of ice is a solid. It keeps its shape.","Water is a liquid. It runs and fills the bottom of a cup. Air is a gas. It spreads out to fill the room."],"adult":["Solids are hard and keep their shape. Liquids are runny: they flow, pour and take the shape of the container. Gases spread out to fill the space, and you often cannot see them.","Tricky cases help. Sand pours, but each grain is a solid. Honey is a slow liquid. Steam is water as a gas."]},"familyTip":"Find a solid, a liquid and a gas in the kitchen. Tip a cup of water: what does the top of the water do?"},"mt_YQkUdIHO8L":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Honey flows slowly. It is a…","choices":["liquid","solid","gas"],"answer":0,"hint":"It pours.","explain":"Honey is a slow liquid."},{"type":"mc","id":"m2","prompt":"Which keeps the same shape in any container?","choices":["a solid","a liquid","a gas"],"answer":0,"hint":"Ice cube in a glass.","explain":"Solids keep their shape."},{"type":"mc","id":"m3","prompt":"Bubbles in fizzy drink are…","choices":["gas","liquid","solid"],"answer":0,"hint":"They float up.","explain":"The bubbles are gas."},{"type":"numeric","id":"m4","prompt":"You sort {n} solids, {m} liquids and 1 gas. How many things?","answer":"n+m+1","hint":"Add all.","explain":"{n} + {m} + 1 = {=n+m+1}.","params":{"n":[1,5],"m":[1,5]}},{"type":"numeric","id":"m5","prompt":"{n} of {=n+m} things pour. How many do not pour?","answer":"m","hint":"Take away.","explain":"{m}.","params":{"n":[1,5],"m":[1,5]}},{"type":"mc","id":"m6","prompt":"Flour pours. Is flour a solid?","choices":["Yes, it is a powder of tiny solid bits","No, it is a liquid","No, it is a gas"],"answer":0,"hint":"One grain.","explain":"Powders are solids."},{"type":"mc","id":"m7","prompt":"Which spreads out to fill a whole box?","choices":["a gas","a liquid","a solid"],"answer":0,"hint":"Spray scent.","explain":"Gases fill the space."}]},"practice":[{"type":"mc","id":"p1","prompt":"Sand pours. Is it a liquid?","choices":["No, each grain is a solid","Yes","It is a gas"],"answer":0,"hint":"Look at one grain.","explain":"Each grain keeps its shape: sand is a solid."},{"type":"mc","id":"p2","prompt":"Which can be squashed easily?","choices":["a gas","a liquid","a solid"],"answer":0,"hint":"Squeeze a balloon.","explain":"Gas particles are far apart, so gases squash."},{"type":"numeric","id":"p3","prompt":"A jar holds {n} bubbles of gas. {m} escape. How many are left?","answer":"n-m","hint":"Take away.","explain":"{=n-m} left.","params":{"n":[6,10],"m":[1,5]}},{"type":"numeric","id":"p4","prompt":"{n} cups of water fill a jug. How many cups fill {m} jugs?","answer":"n*m","hint":"Groups.","explain":"{n} × {m} = {=n*m}.","params":{"n":[2,5],"m":[2,3]}}],"explain":{"kid":["Solids keep their shape. Liquids flow and can be poured. Gases spread out to fill a space.","Sand can pour, but each grain is a tiny solid. It keeps its shape."],"adult":["Grouping by behaviour: does it keep its own shape (solid), flow and keep the same volume (liquid), or spread out to fill any container (gas)? Gases can be squashed; liquids and solids hardly can.","Powders such as sand and flour pour like liquids but are solids, because each grain keeps its shape. Gases are often invisible, so we notice them by smell or by what they push (wind, bubbles)."]},"familyTip":"Squeeze a syringe of air, then a syringe of water (outside, with care). Which one squashes?"},"mt_Pl-nsjYGZ3":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"Water boils at…","choices":["100 °C","0 °C","37 °C"],"answer":0,"hint":"Kettle.","explain":"Water boils at 100 °C."},{"type":"mc","id":"m2","prompt":"Cooling a liquid can make it…","choices":["freeze (turn solid)","boil","vanish"],"answer":0,"hint":"Freezer.","explain":"Cooling freezes it."},{"type":"numeric","id":"m3","prompt":"A drink is {t} °C. It cools by {d} °C. What is it now?","answer":"t-d","hint":"Take away.","explain":"{t} − {d} = {=t-d} °C.","params":{"t":[40,80],"d":[5,30]}},{"type":"numeric","id":"m4","prompt":"Ice is at −{d} °C. How many degrees warmer until it melts at 0 °C?","answer":"d","hint":"Up to zero.","explain":"{d} degrees.","params":{"d":[2,15]}},{"type":"mc","id":"m5","prompt":"Why does chocolate melt in your hand?","choices":["Your hand is warmer than its melting point","Hands are wet","It is a gas"],"answer":0,"hint":"About 34 °C.","explain":"Your hand is above 34 °C."},{"type":"mc","id":"m6","prompt":"We measure temperature with a…","choices":["thermometer","ruler","scale"],"answer":0,"hint":"°C.","explain":"A thermometer."},{"type":"mc","id":"m7","prompt":"Heating water a lot makes…","choices":["steam (a gas)","ice","sand"],"answer":0,"hint":"Kettle.","explain":"Boiling makes steam."}]},"practice":[{"type":"mc","id":"p1","prompt":"Ice melts when it is…","choices":["heated","cooled","squashed"],"answer":0,"hint":"Warm hands.","explain":"Heating melts ice."},{"type":"mc","id":"p2","prompt":"Water freezes at…","choices":["0 °C","100 °C","50 °C"],"answer":0,"hint":"Freezer.","explain":"Water freezes at 0 °C."},{"type":"numeric","id":"p3","prompt":"Water is at {t} °C. How many degrees warmer until it boils at 100 °C?","answer":"100-t","hint":"100 take away.","explain":"100 − {t} = {=100-t}.","params":{"t":[20,90]}},{"type":"numeric","id":"p4","prompt":"Room is {t} °C. Chocolate melts at 34 °C. How many degrees warmer?","answer":"34-t","hint":"Find the gap.","explain":"34 − {t} = {=34-t}.","params":{"t":[15,30]}}],"explain":{"kid":["Heat chocolate and it melts. Put water in the freezer and it turns to ice.","A thermometer tells us how hot or cold something is, in degrees (°C)."],"adult":["Each material changes state at its own temperature. Water melts at 0 °C and boils at 100 °C. Chocolate melts at about 34 °C, which is why it melts in a warm hand.","Heating moves along solid → liquid → gas; cooling goes back. Reading a thermometer at the moment of change is a good first science measurement."]},"familyTip":"Put a square of chocolate in your hand and one on a cold plate. Which melts first? Why?"},"mt_Mf-T-fYRLX":{"mastery":{"passMark":3,"draw":4,"pool":[{"type":"mc","id":"m1","prompt":"How do you get salt back from salty water?","choices":["Evaporate the water","Use a sieve","Use a magnet"],"answer":0,"hint":"Heat it gently.","explain":"Evaporating leaves the salt."},{"type":"mc","id":"m2","prompt":"How do you get sand out of water?","choices":["Filter it","Evaporate only","Stir it"],"answer":0,"hint":"Sand is insoluble.","explain":"A filter catches the sand."},{"type":"mc","id":"m3","prompt":"A material that dissolves is…","choices":["soluble","insoluble","opaque"],"answer":0,"hint":"Sol-.","explain":"Soluble means it dissolves."},{"type":"numeric","id":"m4","prompt":"{n} g of salt in {m} g of water. Mass of the salt water, in g?","answer":"n+m","hint":"Nothing is lost.","explain":"{=n+m} g.","params":{"n":[5,25],"m":[50,150]}},{"type":"numeric","id":"m5","prompt":"You start with {n} g of sugar and dissolve it. How many grams are still in the water?","answer":"n","hint":"It's still there.","explain":"{n} g.","params":{"n":[5,40]}},{"type":"mc","id":"m6","prompt":"Is dissolving reversible?","choices":["Yes, evaporate to get the solid back","No, never"],"answer":0,"hint":"Salt from sea water.","explain":"You can get the solid back."},{"type":"mc","id":"m7","prompt":"Warm water usually dissolves sugar…","choices":["faster","slower","not at all"],"answer":0,"hint":"Tea!","explain":"Warmer water dissolves sugar faster."}]},"practice":[{"type":"mc","id":"p1","prompt":"Sugar stirred into water…","choices":["dissolves","melts into a gas","stays as lumps"],"answer":0,"hint":"It seems to vanish.","explain":"It dissolves to make a solution."},{"type":"mc","id":"p2","prompt":"Sand in water…","choices":["does not dissolve","dissolves","turns to gas"],"answer":0,"hint":"It sinks.","explain":"Sand is insoluble."},{"type":"numeric","id":"p3","prompt":"You dissolve {n} g of salt in water. How much salt is left after it evaporates, in g?","answer":"n","hint":"Salt stays behind.","explain":"All {n} g is left.","params":{"n":[5,30]}},{"type":"numeric","id":"p4","prompt":"{n} g of sugar goes into {m} g of water. What is the mass of the solution, in g?","answer":"n+m","hint":"Add the masses.","explain":"{n} + {m} = {=n+m} g.","params":{"n":[5,20],"m":[100,200]}}],"explain":{"kid":["Stir sugar into warm water. The sugar seems to vanish. It has dissolved and made a solution.","Leave salty water in a warm place. The water dries up, and the salt is left behind."],"adult":["A soluble solid (salt, sugar) breaks into particles too small to see and spreads through the liquid: a solution. An insoluble solid (sand, chalk) does not, and can be caught by a filter.","Dissolving is reversible: evaporating the water leaves the solid behind. The mass is not lost; the dissolved solid is still there."]},"familyTip":"Try sugar, sand and salt in three cups of warm water. Which dissolve? Leave the salt water on a sunny sill for a few days."}});
